class LFUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.data = {}
        self.tick = 0

    def get(self, key):
        if self.cap <= 0:
            return None
        if key not in self.data:
            return None
        self.tick += 1
        v, f, _ = self.data[key]
        self.data[key] = [v, f + 1, self.tick]
        return v

    def put(self, key, value):
        if self.cap <= 0:
            return
        self.tick += 1
        if key in self.data:
            self.data[key][0] = value
            self.data[key][1] += 1
            self.data[key][2] = self.tick
            return
        if len(self.data) >= self.cap:
            # Evict least frequently used; ties broken by least recently used (smallest tick)
            victim = min(self.data, key=lambda k: (self.data[k][1], self.data[k][2]))
            del self.data[victim]
        self.data[key] = [value, 1, self.tick]
```

