class Bus:
    def __init__(self):
        self.subs = {}

    def on(self, topic, handler, priority=0):
        if topic not in self.subs:
            self.subs[topic] = []
        entry = (priority, handler)
        self.subs[topic].append(entry)
        # Sort: higher priority first (descending). Stable sort preserves subscription order for equal priorities.
        self.subs[topic].sort(key=lambda p: p[0], reverse=True)

        removed = [False]

        def unsubscribe():
            if removed[0]:
                return
            removed[0] = True
            if topic in self.subs:
                try:
                    self.subs[topic].remove(entry)
                except ValueError:
                    pass  # Already gone; harmless as specified

        return unsubscribe

    def emit(self, topic, *args):
        if topic not in self.subs:
            return 0
        # Snapshot the current list to avoid calling handlers added during this emit
        # and to respect removals of handlers that unsubscribe mid-emit.
        snapshot = list(self.subs[topic])
        n = 0
        for _, h in snapshot:
            # Check if this specific subscription is still present before calling
            if topic in self.subs and (_, h) in self.subs[topic]:
                h(*args)
                n += 1
        return n
