    def __init__(self):
        self.subs = {}
        self._sub_id = 0

    def on(self, topic, handler, priority=0):
        if topic not in self.subs:
            self.subs[topic] = []
        sub_id = self._sub_id
        self._sub_id += 1
        self.subs[topic].append((priority, sub_id, handler))
        self.subs[topic].sort(key=lambda x: -x[0])

        def unsubscribe():
            entries = self.subs.get(topic, [])
            for i, (p, sid, h) in enumerate(entries):
                if sid == sub_id:
                    entries.pop(i)
                    break

        return unsubscribe

    def emit(self, topic, *args):
        entries = self.subs.get(topic, [])
        snapshot = list(entries)
        n = 0
        for _, _, h in snapshot:
            if any(sid == sub_id for p, sub_id, handler in entries if handler == h):
                h(*args)
                n += 1
        return n
