def wrap(text, width):
    if width < 1:
        raise ValueError("width must be >= 1")

    if not text or not text.strip():
        return []

    # Split text into paragraphs by one or more blank lines
    paragraphs = []
    current_para = []
    for line in text.splitlines():
        if line.strip() == "":
            if current_para:
                paragraphs.append(" ".join(current_para))
                current_para = []
        else:
            # Split line into words and add to current paragraph
            current_para.extend(line.split())

    # Don't forget the last paragraph if it exists
    if current_para:
        paragraphs.append(" ".join(current_para))

    result_lines = []

    for para in paragraphs:
        words = para.split()
        line = ""

        for w in words:
            # Handle words longer than width by breaking them
            while len(w) > width:
                # If we have content in current line, flush it first
                if line:
                    result_lines.append(line)
                    line = ""
                # Take a chunk of size 'width' from the word
                result_lines.append(w[:width])
                w = w[width:]

            # Now w is <= width
            if line == "":
                line = w
            elif len(line) + 1 + len(w) <= width:
                line = line + " " + w
            else:
                result_lines.append(line)
                line = w

        if line:
            result_lines.append(line)

        # Add empty line between paragraphs (but not after the last one)
        result_lines.append("")

    # Remove the trailing empty line added after the last paragraph
    if result_lines and result_lines[-1] == "":
        result_lines.pop()

    # Filter out any empty lines that shouldn't be there (except paragraph separators)
    # Actually, we need exactly one "" between paragraphs, which we already added
    # But if a paragraph produced no lines (shouldn't happen with valid input), we'd have issues

    return result_lines
