def wrap(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")

    if not text or not text.strip():
        return []

    paragraphs = text.split('\n\n')
    result = []

    for para in paragraphs:
        if not para.strip():
            continue

        words = para.split()
        if not words:
            continue

        lines = []
        current_line = ""

        for word in words:
            if not current_line:
                # Start of a new line
                if len(word) <= width:
                    current_line = word
                else:
                    # Word longer than width: cut it
                    while len(word) > width:
                        lines.append(word[:width])
                        word = word[width:]
                    current_line = word
            else:
                # Try to add word to current line
                if len(current_line) + 1 + len(word) <= width:
                    current_line = current_line + " " + word
                else:
                    # Word doesn't fit, finish current line
                    lines.append(current_line)
                    # Now handle the word on a new line
