                        current_line = word
                    else:
                        # Word longer than width: cut it
                        while len(word) > width:
                            lines.append(word[:width])
                            word = word[width:]
                        current_line = word

        if current_line:
            lines.append(current_line)

        result.extend(lines)
        result.append("")

    # Remove the trailing empty string added after the last paragraph
    if result and result[-1] == "":
        result.pop()

    return result
