```python
def wrap(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")

    if not text or not text.strip():
        return []

    paragraphs = text.split('\n\n')
    result_lines = []

    for para in paragraphs:
        # Collapse all whitespace within the paragraph to single spaces and strip edges
        words = para.split()
        if not words:
            continue

        lines = []
        current_line = ""

        for word in words:
            # Determine if we can add the word to the current line
            # Need space for the word itself, plus a space if line is not empty
            required_length = len(word) + (1 if current_line else 0)

            if len(current_line) + required_length <= width:
                # Word fits
                if current_line:
                    current_line += " " + word
                else:
                    current_line = word
            else:
                # Word doesn't fit, push current line and start new one
                if current_line:
                    lines.append(current_line)

                # Handle word longer than width (cut it)
                if len(word) > width:
                    while len(word) > width:
                        lines.append(word[:width])
                        word = word[width:]
                    current_line = word
                else:
                    current_line = word

        if current_line:
            lines.append(current_line)

        if result_lines:
            result_lines.append("")  # Blank line between paragraphs
        result_lines.extend(lines)

    return result_lines
