def group_averages(rows):
    sums = {}
    counts = {}
    first_seen = {}

    for name, value in rows:
        # Normalize key: strip whitespace and lowercase for grouping
        key = name.strip().lower()

        # Record the first spelling seen (with whitespace removed, original case)
        if key not in first_seen:
            first_seen[key] = name.strip()

        # Initialize accumulators if this is the first time seeing this group
        if key not in sums:
            sums[key] = 0
            counts[key] = 0

        # Handle value: None means "no reading" and is ignored entirely
        if value is not None:
            sums[key] += value
            counts[key] += 1

    result = []
    for key in sums:
        label = first_seen[key]
        if counts[key] == 0:
            # Group with no readings at all has average None
            avg = None
        else:
            avg = sums[key] / counts[key]
        result.append((label, avg))

