            v = value_str.lower()
            if v in ("1", "true", "yes", "on"):
                return True
            elif v in ("0", "false", "no", "off"):
                return False
            else:
                raise ValueError(f"Invalid boolean value: {value_str}")
        elif target_type is int:
            return int(value_str)
        elif target_type is float:
            return float(value_str)
        else:
            return value_str

    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Remove prefix and split on double underscore for nesting
        key_part = k[len(prefix):]
        path = key_part.lower().split("__")

        # Traverse to the parent node
        node = cfg
        valid_path = True
        for p in path[:-1]:
            if isinstance(node, dict) and p in node:
                node = node[p]
            else:
                valid_path = False
                break

        if not valid_path:
            continue

        # Check if the final key exists
        final_key = path[-1]
        if not isinstance(node, dict) or final_key not in node:
            continue

        # Get the type of the default value
        default_val = node[final_key]
        target_type = type(default_val)

        try:
            node[final_key] = parse_value(raw, target_type)
        except (ValueError, TypeError):
