    """
    Load configuration from environment variables, overriding defaults.

    - Variables must start with `prefix`.
    - Path is derived from the key after prefix: lowercased, split by '__'.
    - Single underscores are part of the key name.
    - Values are cast to the type of the default value.
    - Booleans accept: 1/true/yes/on (True) and 0/false/no/off (False).
    - Unknown paths or invalid types are ignored.
    - Defaults are not modified.
    """

    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        return obj

    def parse_bool(val):
        v = val.lower().strip()
        if v in ('1', 'true', 'yes', 'on'):
            return True
        if v in ('0', 'false', 'no', 'off'):
            return False
        raise ValueError(f"Invalid boolean value: {val}")

    def convert_value(raw, target_type):
        if target_type is bool:
            return parse_bool(raw)
        try:
            return target_type(raw)
        except (ValueError, TypeError):
            return None

    def set_nested(node, path, value):
        for key in path[:-1]:
            if key not in node or not isinstance(node[key], dict):
                return False
            node = node[key]

        key = path[-1]
        if key not in node:
            return False

        node[key] = value
        return True

    # Deep copy to prevent mutation of defaults
    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Remove prefix and lowercase
        key_part = k[len(prefix):].lower()

        # Split by double underscore only
        path = key_part.split('__')

        # Traverse to find the target type and ensure path exists
        node = cfg
        valid_path = True

        # Check if path exists in defaults to determine target type and validity
        current_default = defaults
        for p in path:
            if isinstance(current_default, dict) and p in current_default:
                current_default = current_default[p]
            else:
                valid_path = False
                break

        if not valid_path:
            continue

        target_type = type(current_default)

        # Convert value
        try:
            converted = convert_value(raw, target_type)
            if converted is None and target_type != type(None):
                # Conversion failed (returned None from except block)
                continue
        except ValueError:
            # Invalid format (e.g., bad bool string)
            continue

        # Set value in config
        set_nested(cfg, path, converted)

