def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from environment variables, overriding defaults.

    Args:
        defaults: Nested dict of default values.
        env: Dict of environment variables (e.g., os.environ).
        prefix: Prefix for environment variables (default "APP_").

    Returns:
        A new config dict with defaults overridden by matching env vars.
        The defaults object is not modified.

    Env var format:
        PREFIX + PATH where PATH is lowercased and uses double underscores
        for nesting (e.g., APP_DB__MAX_CONNS overrides config["db"]["max_conns"]).
        A single underscore is part of the key name.

    Type conversion:
        - bool: accepts 1/true/yes/on or 0/false/no/off (case-insensitive)
        - int/float: parsed numerically
        - other: kept as string

    Variables without the prefix or paths not in defaults are ignored.
    """
    def _deep_copy(obj):
        """Create a deep copy of nested dicts/lists without importing copy."""
        if isinstance(obj, dict):
            return {k: _deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_deep_copy(item) for item in obj]
        else:
            return obj

    def _parse_bool(value):
        """Parse a string to boolean, raising ValueError for invalid values."""
        val = value.strip().lower()
        if val in ('1', 'true', 'yes', 'on'):
            return True
        elif val in ('0', 'false', 'no', 'off'):
            return False
        else:
            raise ValueError(f"Invalid boolean value: {value}")

    def _convert_value(value, target_type):
        """Convert a string value to the target type."""
        if target_type is bool:
            return _parse_bool(value)
        elif target_type is int:
            return int(value)
        elif target_type is float:
            return float(value)
        else:
            # For str or any other type, return as string
            return value

    # Create a deep copy to avoid modifying defaults
    cfg = _deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Extract path: remove prefix, lowercase, split on double underscore
        path_str = k[len(prefix):].lower()
        path = path_str.split("__")

        # Navigate to the parent node
        node = cfg
        valid = True
        for p in path[:-1]:
            if p not in node or not isinstance(node[p], dict):
                # Path doesn't exist in defaults, ignore this env var
                valid = False
                break
            node = node[p]

        if not valid:
            continue

        final_key = path[-1]
        if final_key not in node:
            # Path doesn't exist in defaults, ignore this env var
            continue

        # Get the type of the default value
        default_value = node[final_key]
        target_type = type(default_value)

        try:
            converted_value = _convert_value(raw, target_type)
            node[final_key] = converted_value
        except (ValueError, TypeError):
            # Invalid conversion, ignore this env var (or could raise)
            # Based on spec: "anything else raises ValueError" for bool
            # For int/float, parsing errors would naturally raise
            # We'll let them propagate as they indicate bad input
            raise

    return cfg
