import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parens. Reject unknown chars early.
    if not s or not s.strip():
        raise ValueError("empty input")

    # Check for invalid characters before tokenizing
    stripped = s.replace(" ", "")
    if not stripped:
        raise ValueError("empty input")

    valid_pattern = re.compile(r'^[\d\.\+\-\*\/\^\(\)]+$')
    if not valid_pattern.match(stripped):
        raise ValueError("invalid characters")

    toks = re.findall(r"\d+\.?\d*|\.\d+|[-+*/^()]", s)
    if not toks:
        raise ValueError("empty input")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expect(tok):
        t = take()
        if t != tok:
            raise ValueError(f"expected {tok}")
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = power()
        while peek() in ("*", "/"):
            op = take()
            r = power()
            v = v * r if op == "*" else v / r
        return v

    def power():
        # Right-associative exponentiation with unary binding tighter than base
        # but exponent may carry its own sign: 2^-1 -> 2 ** (-1)
        v = atom()
        if peek() == "^":
            take()
            # Exponent is a signed atom (unary binds tighter than ^ on the right)
            exp = signed_atom()
            v = v ** exp
            # Right-associative: continue parsing more ^ if present
            while peek() == "^":
                take()
                exp = signed_atom()
                v = v ** exp
        return v

    def signed_atom():
        # Handle unary + or - for exponent (tighter than ^ on the right side)
        if peek() == "+":
            take()
            return atom()
        if peek() == "-":
            take()
            return -atom()
        return atom()

    def atom():
        t = peek()
        if t is None:
            raise ValueError("missing operand")
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("unbalanced parentheses")
            take()
            return v
        if t in ("+", "-", "*", "/", "^"):
            raise ValueError("missing operand")
        # Must be a number
        take()
        return float(t)

    result = expr()
    if pos != len(toks):
        raise ValueError("extra input")
    return result
