from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl):
        self.cap = capacity
        self.ttl = ttl
        self.d = OrderedDict()

    def _is_expired(self, exp, now):
        # Entry is expired when now >= stored_at + ttl (i.e., now >= exp)
        return now >= exp

    def get(self, key, now):
        if key not in self.d:
            return None
        v, exp = self.d[key]
        if self._is_expired(exp, now):
            del self.d[key]
            return None
        # Move to end to mark as most recently used
        self.d.move_to_end(key)
        return v

    def put(self, key, value, now):
        if self.cap <= 0:
            return
        exp = now + self.ttl
        if key in self.d:
            # Update existing key: replace value, restart ttl, make it most recently used
            self.d[key] = (value, exp)
            self.d.move_to_end(key)
            return

        # New key: first drop every expired entry
        expired_keys = [k for k, (v, e) in self.d.items() if self._is_expired(e, now)]
        for k in expired_keys:
            del self.d[k]

        # Only if still full, evict the least recently used live entry
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)

        self.d[key] = (value, exp)

    def size(self, now):
        # Count only live (non-expired) entries
        count = 0
        for k, (v, e) in self.d.items():
            if not self._is_expired(e, now):
                count += 1
        return count
