The bug exists because `fnmatch` treats `*` as matching everything including `/`, and does not support `**`. I will implement a custom recursive matcher that respects the directory separator rules and supports `**`.

```python
def glob_match(pattern, path):
    """
    Match a glob pattern against a path.

    Rules:
    - '*' matches any run of characters except '/' (including none)
    - '?' matches exactly one character except '/'
    - '**' matches any characters including '/'
    - '**/' matches zero or more whole directories
    - '[abc]', '[a-c]', '[!abc]' character classes (never match '/')
    - Backslash escapes the next character
    - Everything else is literal and case-sensitive
    - Leading dot is not special
    """

    def match_here(p_idx, s_idx):
        """Match pattern[p_idx:] against path[s_idx:]"""
        while p_idx < len(pattern):
            p_char = pattern[p_idx]

            # Handle escape
            if p_char == '\\':
                if p_idx + 1 >= len(pattern):
                    return False  # Trailing backslash
                if s_idx >= len(path) or path[s_idx] != pattern[p_idx + 1]:
                    return False
                p_idx += 2
                s_idx += 1
                continue

            # Handle **
            if p_char == '*' and p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '*':
                # Check if followed by /
                if p_idx + 2 < len(pattern) and pattern[p_idx + 2] == '/':
                    # **/ matches zero or more directories
                    # Try matching rest of pattern at current position (zero dirs)
                    if match_here(p_idx + 3, s_idx):
                        return True
                    # Try consuming one directory at a time
                    i = s_idx
                    while i < len(path):
                        if path[i] == '/':
                            if match_here(p_idx + 3, i + 1):
                                return True
                        i += 1
                    return False
                else:
                    # ** matches anything including /
                    # Try matching rest of pattern at every position
                    for i in range(s_idx, len(path) + 1):
                        if match_here(p_idx + 2, i):
                            return True
                    return False

            # Handle *
            if p_char == '*':
                # Match zero or more non-/ characters
                # Try matching rest of pattern at every position until /
                for i in range(s_idx, len(path) + 1):
                    if i < len(path) and path[i] == '/':
                        break
                    if match_here(p_idx + 1, i):
                        return True
                return False

            # Handle ?
            if p_char == '?':
                if s_idx >= len(path) or path[s_idx] == '/':
                    return False
                p_idx += 1
                s_idx += 1
                continue

            # Handle character class [...]
            if p_char == '[':
                close_idx = find_class_end(p_idx)
                if close_idx == -1:
                    # No closing bracket, treat as literal
                    if s_idx >= len(path) or path[s_idx] != p_char:
                        return False
                    p_idx += 1
                    s_idx += 1
                    continue

                if s_idx >= len(path):
                    return False

                char_class = pattern[p_idx + 1:close_idx]
                matched = match_char_class(char_class, path[s_idx])

                if not matched:
                    return False

                p_idx = close_idx + 1
                s_idx += 1
                continue

            # Literal match
            if s_idx >= len(path) or path[s_idx] != p_char:
                return False

            p_idx += 1
            s_idx += 1

        return s_idx == len(path)

    def find_class_end(start):
        """Find the closing ] for a character class starting at start"""
        i = start + 1
        if i < len(pattern) and pattern[i] == '!':
            i += 1
        if i < len(pattern) and pattern[i] == ']':
            i += 1
        while i < len(pattern) and pattern[i] != ']':
            if pattern[i] == '\\':
                i += 2
            else:
                i += 1
        return i if i < len(pattern) else -1

    def match_char_class(char_class, char):
        """Check if char matches the character class specification"""
        if not char_class:
            return False

        negate = False
        idx = 0

        if char_class[0] == '!':
            negate = True
            idx = 1

        matched = False
        while idx < len(char_class):
            c = char_class[idx]

            # Handle escape in class
            if c == '\\' and idx + 1 < len(char_class):
                if char == char_class[idx + 1]:
                    matched = True
                    break
                idx += 2
                continue

            # Check for range
            if idx + 2 < len(char_class) and char_class[idx + 1] == '-':
                end_c = char_class[idx + 2]
                if end_c == '\\' and idx + 3 < len(char_class):
                    end_c = char_class[idx + 3]
                    idx += 1
                if c <= char <= end_c:
                    matched = True
                    break
                idx += 3
            else:
                if char == c:
                    matched = True
                    break
                idx += 1

        return not matched if negate else matched

    return match_here(0, 0)
