def set_path(obj, path, value):
    """
    Returns a new structure where the location named by path holds value.
    The original obj and everything reachable from it is left untouched.
    """
    if not path:
        raise ValueError("Path cannot be empty")
    if path.startswith(".") or path.endswith("."):
        raise ValueError("Path cannot start or end with a dot")
    if ".." in path:
        raise ValueError("Path cannot contain empty segments")

    # Validate and parse parts
    # We need to handle "a.b[2].c" -> ["a", "b", "[2]", "c"]
    # But the current split logic in the bug is flawed.
    # Let's write a robust parser.

    tokens = []
    current = []
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current:
                tokens.append(('key', ''.join(current)))
                current = []
            # if current is empty, it means we had ".." which is caught above, 
            # or leading/trailing dot caught above.
        elif ch == '[':
            if current:
                tokens.append(('key', ''.join(current)))
                current = []
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j == len(path):
                raise ValueError("Unclosed bracket in path")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError("Empty index in path")
            if not index_str.isdigit():
                # Check for negative or non-digit
                if index_str.startswith('-') and index_str[1:].isdigit():
                    raise ValueError("Negative indices not supported")
                raise ValueError("Invalid index in path")
            tokens.append(('index', int(index_str)))
            i = j # move to ']'
        else:
            current.append(ch)
        i += 1

    if current:
        tokens.append(('key', ''.join(current)))

    if not tokens:
        raise ValueError("Path cannot be empty")

    # First step must be a key and obj must be a dict
    if tokens[0][0] != 'key':
        raise ValueError("First step must be a key")
    if not isinstance(obj, dict):
        raise TypeError("Root object must be a dict")

    # Deep copy function to ensure immutability of original
    def deep_copy(item):
        if isinstance(item, dict):
            return {k: deep_copy(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [deep_copy(v) for v in item]
        else:
            return item

    result = deep_copy(obj)

    # Navigate and build structure
    current_node = result

    # Process all tokens except the last one to navigate/create containers
    for i in range(len(tokens) - 1):
        token_type, token_val = tokens[i]
        next_type, _ = tokens[i+1]

        if token_type == 'key':
            if not isinstance(current_node, dict):
                raise TypeError("Cannot use key on non-dict")

            key = token_val
            if key not in current_node:
                # Create next container based on next step
                if next_type == 'index':
                    current_node[key] = []
                else:
                    current_node[key] = {}

            current_node = current_node[key]

        elif token_type == 'index':
            if not isinstance(current_node, list):
                raise TypeError("Cannot use index on non-list")

            idx = token_val
            if idx < 0:
                raise ValueError("Negative indices not supported")

            # Pad list if necessary
            while len(current_node) <= idx:
                current_node.append(None)

            if current_node[idx] is None:
                # Create next container based on next step
                if next_type == 'index':
                    current_node[idx] = []
                else:
                    current_node[idx] = {}

            current_node = current_node[idx]

    # Set the final value
    last_type, last_val = tokens[-1]

    if last_type == 'key':
        if not isinstance(current_node, dict):
            raise TypeError("Cannot set key on non-dict")
        current_node[last_val] = value
    elif last_type == 'index':
        if not isinstance(current_node, list):
            raise TypeError("Cannot set index on non-list")

        idx = last_val
        if idx < 0:
            raise ValueError("Negative indices not supported")

        # Pad list if necessary
        while len(current_node) <= idx:
            current_node.append(None)

        current_node[idx] = value

    return result
