def set_path(obj, path, value):
    """
    Set a value at a nested path in a dictionary, returning a new structure
    without modifying the original obj or any reachable mutable parts.

    Args:
        obj: The root dictionary (must be a dict).
        path: Dot-separated string with optional list indexes (e.g., "a.b[2].c").
        value: The value to set at the specified path.

    Returns:
        A new dictionary structure with the value set at the path.

    Raises:
        ValueError: If path is empty, malformed, or starts with an index.
        TypeError: If a step encounters a type mismatch (key on list/scalar, index on dict/scalar).
    """
    if not path or path.startswith(".") or path.startswith("[") or ".." in path:
        raise ValueError("Path is empty or malformed")

    # Validate and parse path segments
    parts = []
    i = 0
    while i < len(path):
        if path[i] == ".":
            i += 1
            continue
        if path[i] == "[":
            # Find closing bracket
            close_idx = path.find("]", i)
            if close_idx == -1:
                raise ValueError("Malformed path: unclosed bracket")
            index_str = path[i+1:close_idx]
            if not index_str.isdigit():
                raise ValueError("Malformed path: invalid index")
            parts.append(("index", int(index_str)))
            i = close_idx + 1
        elif path[i].isalnum() or path[i] == "_":
            # Read key
            start = i
            while i < len(path) and (path[i].isalnum() or path[i] == "_"):
                i += 1
            parts.append(("key", path[start:i]))
        else:
            raise ValueError("Malformed path: invalid character")

    if not parts:
        raise ValueError("Path is empty")

    if parts[0][0] != "key":
        raise ValueError("Path must start with a key")

    if not isinstance(obj, dict):
        raise TypeError("Root object must be a dict")

    def deep_copy_structure(o):
        """Create a shallow copy of containers, but we'll do deep copy as we traverse."""
        if isinstance(o, dict):
            return dict(o)
        elif isinstance(o, list):
            return list(o)
        else:
            return o

    # Build the new structure with deep copying
    def clone_with_path(root, path_parts, target_value):
        if not path_parts:
            return target_value

        step_type, step_val = path_parts[0]
        remaining = path_parts[1:]

        if step_type == "key":
            if not isinstance(root, dict):
                raise TypeError("Expected dict for key step")

            new_dict = {}
            for k, v in root.items():
                if k == step_val:
                    # This is the path we're modifying - deep copy and recurse
                    if isinstance(v, (dict, list)):
                        new_dict[k] = clone_with_path(deep_copy_structure(v), remaining, target_value)
                    else:
                        new_dict[k] = clone_with_path(v, remaining, target_value)
                else:
                    # Other keys get deep copied
                    new_dict[k] = deep_copy_structure(v)

            # If key doesn't exist, we need to create it
            if step_val not in new_dict:
                # Determine what to create based on next step
                if remaining:
                    next_type, next_val = remaining[0]
                    if next_type == "index":
                        new_dict[step_val] = clone_with_path([], remaining, target_value)
                    else:
                        new_dict[step_val] = clone_with_path({}, remaining, target_value)
                else:
                    new_dict[step_val] = target_value

            return new_dict

        else:  # index
            if not isinstance(root, list):
                raise TypeError("Expected list for index step")

            new_list = [deep_copy_structure(item) for item in root]
            idx = step_val

            if idx > len(new_list):
                # Pad with None
                new_list.extend([None] * (idx - len(new_list)))

            if idx == len(new_list):
                # Append case
                if remaining:
                    next_type, next_val = remaining[0]
                    if next_type == "index":
                        new_list.append(clone_with_path([], remaining, target_value))
                    else:
                        new_list.append(clone_with_path({}, remaining, target_value))
                else:
                    new_list.append(target_value)
            else:
                # Existing index
                current = new_list[idx]
                if remaining:
                    if isinstance(current, (dict, list)):
                        new_list[idx] = clone_with_path(deep_copy_structure(current), remaining, target_value)
                    elif current is None:
                        # Create appropriate container based on next step
                        next_type, next_val = remaining[0]
                        if next_type == "index":
                            new_list[idx] = clone_with_path([], remaining, target_value)
                        else:
                            new_list[idx] = clone_with_path({}, remaining, target_value)
                    else:
                        raise TypeError("Type mismatch: cannot traverse into scalar")
                else:
                    new_list[idx] = target_value

            return new_list

    return clone_with_path(obj, parts, value)
