def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")
    if not path:
        raise ValueError("path cannot be empty")

    # Deep copy helper
    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        if isinstance(o, list):
            return [deep_copy(v) for v in o]
        return o

    root = deep_copy(obj)

    # Parse path into steps: list of ('key', str) or ('index', int)
    steps = []
    raw_parts = path.split(".")
    for i, part in enumerate(raw_parts):
        if part == "":
            raise ValueError(f"Malformed path: empty segment in '{path}'")
        # Handle multiple indices like "a[0][1]" or mixed "a.b[0].c"
        # We need to split part into keys and indices
        current = part
        while current:
            if current.startswith("["):
                # Extract index
                bracket_end = current.find("]")
                if bracket_end == -1:
                    raise ValueError(f"Malformed path: unclosed bracket in '{path}'")
                idx_str = current[1:bracket_end]
                if not idx_str.isdigit():
                    raise ValueError(f"Malformed path: invalid index '{idx_str}' in '{path}'")
                steps.append(('index', int(idx_str)))
                current = current[bracket_end + 1:]
            else:
                # Extract key up to next '[' or end
                bracket_start = current.find("[")
                if bracket_start == -1:
                    steps.append(('key', current))
                    current = ""
                else:
                    steps.append(('key', current[:bracket_start]))
                    current = current[bracket_start:]

    if not steps:
        raise ValueError("path cannot be empty")

    # First step must be a key
    if steps[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Navigate and build missing containers
    node = root
    for i in range(len(steps) - 1):
        step_type, step_val = steps[i]
        next_type, next_val = steps[i + 1]

        if step_type == 'key':
            if not isinstance(node, dict):
                raise TypeError(f"Expected dict at path segment, got {type(node).__name__}")
            if step_val not in node:
                # Create missing container based on next step
                node[step_val] = [] if next_type == 'index' else {}
            node = node[step_val]
        else:  # index
            if not isinstance(node, list):
                raise TypeError(f"Expected list at path segment, got {type(node).__name__}")
            if step_val < 0:
                raise ValueError(f"Negative index not allowed: {step_val}")
            # Extend list if needed
            while len(node) <= step_val:
                node.append(None)
            if node[step_val] is None:
                # Create missing container based on next step
                node[step_val] = [] if next_type == 'index' else {}
            node = node[step_val]

    # Set final value
    last_type, last_val = steps[-1]
    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError(f"Expected dict at final path segment, got {type(node).__name__}")
        node[last_val] = value
    else:  # index
        if not isinstance(node, list):
            raise TypeError(f"Expected list at final path segment, got {type(node).__name__}")
        if last_val < 0:
            raise ValueError(f"Negative index not allowed: {last_val}")
        # Extend list if needed (append or pad)
        while len(node) <= last_val:
            node.append(None)
        node[last_val] = value

    return root
