import re


def glob_match(pattern, path):
    """
    Match a glob pattern against a path.

    Rules:
    - "*" matches any run of characters except "/" (including none)
    - "?" matches exactly one character except "/"
    - "**" matches any characters including "/"
    - "**/" matches zero or more whole directories
    - "[abc]" matches one character from the set
    - "[a-c]" matches one character in the range
    - "[!abc]" matches one character outside the set
    - A character class never matches "/"
    - Backslash makes the next character literal
    - Everything else is literal and case-sensitive
    - Leading dot is not special
    """
    regex = _pattern_to_regex(pattern)
    return re.fullmatch(regex, path) is not None


def _pattern_to_regex(pattern):
    """Convert a glob pattern to a regular expression."""
    i = 0
    n = len(pattern)
    regex_parts = []

    while i < n:
        c = pattern[i]

        if c == '\\':
            # Escape next character
            if i + 1 < n:
                regex_parts.append(re.escape(pattern[i + 1]))
                i += 2
            else:
                regex_parts.append(re.escape('\\'))
                i += 1

        elif c == '*':
            # Check for **
            if i + 1 < n and pattern[i + 1] == '*':
                # Check for **/
                if i + 2 < n and pattern[i + 2] == '/':
                    # **/ matches zero or more whole directories
                    # This means it matches "" or "dir/" or "dir1/dir2/" etc.
                    regex_parts.append('(?:.*/)?')
                    i += 3
                else:
                    # ** matches anything including /
                    regex_parts.append('.*')
                    i += 2
            else:
                # * matches anything except /
                regex_parts.append('[^/]*')
                i += 1

        elif c == '?':
            # ? matches exactly one character except /
            regex_parts.append('[^/]')
            i += 1

        elif c == '[':
            # Character class
            class_end = _find_class_end(pattern, i)
            if class_end == -1:
                # No closing bracket, treat as literal
                regex_parts.append(re.escape(c))
                i += 1
            else:
                class_content = pattern[i + 1:class_end]
                regex_parts.append(_convert_char_class(class_content))
                i = class_end + 1

        else:
            # Literal character
            regex_parts.append(re.escape(c))
            i += 1

    return ''.join(regex_parts)


def _find_class_end(pattern, start):
    """Find the closing bracket of a character class starting at start."""
    i = start + 1
    n = len(pattern)

    # Handle special case where ] or ! is first character in class
    if i < n and pattern[i] in '!^':
        i += 1
    if i < n and pattern[i] == ']':
        i += 1

    while i < n:
        if pattern[i] == ']':
            return i
        elif pattern[i] == '\\':
            i += 2  # Skip escaped character
        else:
            i += 1

    return -1  # No closing bracket found


def _convert_char_class(content):
