def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    `obj` and everything reachable from it is left untouched (deep copy).

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing containers for index steps are created as lists.
    - Index == len(list) appends.
    - Index > len(list) pads with None up to that index.
    - Type mismatch (key on list/scalar, index on dict/scalar) raises TypeError.
    - Empty or malformed path raises ValueError.
    - First step must be a key; obj must be a dict.
    """
    import copy

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before parsing
    # Check for empty segments, leading/trailing dots, invalid indexes
    if path.startswith('.') or path.endswith('.'):
        raise ValueError("path cannot start or end with a dot")

    # Parse the path into steps
    # We need to handle cases like "a.b[2].c" -> ['a', 'b', '[2]', 'c']
    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError("empty segment in path")
            steps.append(current)
            current = ""
        elif ch == '[':
            if current != "":
                steps.append(current)
                current = ""
            # Find the closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '[':
                    raise ValueError("nested brackets not allowed")
                j += 1
            if j >= len(path):
                raise ValueError("unclosed bracket in path")
            index_str = path[i+1:j]
            if index_str == "":
                raise ValueError("empty index in path")
            if index_str.startswith('-'):
                raise ValueError("negative indexes not allowed")
            if not index_str.isdigit():
                raise ValueError("invalid index in path")
            steps.append(f"[{index_str}]")
            i = j
        else:
            current += ch
        i += 1

    if current != "":
        steps.append(current)

    if not steps:
        raise ValueError("path is empty")

    # First step must be a key (not an index)
    if steps[0].startswith('['):
        raise ValueError("first step must be a key")

    # Deep copy the object to ensure immutability of the original
    result = copy.deepcopy(obj)

    node = result

    # Navigate/create path up to the second-to-last step
    for idx, step in enumerate(steps[:-1]):
        next_step = steps[idx + 1]
        is_next_index = next_step.startswith('[')

        if step.startswith('['):
            # Index step
            index = int(step[1:-1])
            if not isinstance(node, list):
                raise TypeError("cannot index into a non-list")

            # Handle list expansion
            if index == len(node):
                # Append new container
                if is_next_index:
                    node.append([])
                else:
                    node.append({})
            elif index > len(node):
                # Pad with None and then append
                while len(node) < index:
                    node.append(None)
                if is_next_index:
                    node.append([])
                else:
                    node.append({})
            else:
                # Index exists
                if node[index] is None:
                    if is_next_index:
                        node[index] = []
                    else:
                        node[index] = {}
                elif is_next_index and not isinstance(node[index], list):
                    raise TypeError("expected list at index")
                elif not is_next_index and not isinstance(node[index], dict):
                    raise TypeError("expected dict at key")

            node = node[index]
        else:
            # Key step
            if not isinstance(node, dict):
                raise TypeError("cannot access key on a non-dict")

            if step not in node:
                if is_next_index:
                    node[step] = []
                else:
                    node[step] = {}
            elif is_next_index and not isinstance(node[step], list):
                raise TypeError("expected list at key")
            elif not is_next_index and not isinstance(node[step], dict):
                raise TypeError("expected dict at key")

            node = node[step]

    # Handle the last step (set the value)
    last_step = steps[-1]
    if last_step.startswith('['):
        index = int(last_step[1:-1])
        if not isinstance(node, list):
            raise TypeError("cannot index into a non-list")

        if index == len(node):
            node.append(value)
        elif index > len(node):
            while len(node) < index:
                node.append(None)
            node.append(value)
        else:
            node[index] = value
    else:
        if not isinstance(node, dict):
            raise TypeError("cannot set key on a non-dict")
        node[last_step] = value

    return result
```

