def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    `obj` and everything reachable from it is left untouched (deep copy semantics).

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing list indices: index == len appends; index > len pads with None.
    - Type mismatch (key on list/scalar, index on dict/scalar) raises TypeError.
    - Empty, malformed, or negative indices raise ValueError.
    - First step must be a key; obj must be a dict.
    """
    import copy

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before parsing
    if path.startswith(".") or path.endswith("."):
        raise ValueError(f"Malformed path: {path}")
    if ".." in path:
        raise ValueError(f"Malformed path: {path}")

    # Tokenize: split by '.' but keep bracket groups attached to previous key if needed
    # Strategy: replace '[' with '.[' then split, but handle empty strings
    raw_parts = path.replace("[", ".[").split(".")
    parts = [p for p in raw_parts if p != ""]

    if not parts:
        raise ValueError("path is empty or malformed")

    # Parse parts into a list of (type, key/index)
    # type: 'key' or 'index'
    steps = []
    for p in parts:
        if p.startswith("["):
            if not p.endswith("]"):
                raise ValueError(f"Malformed path segment: {p}")
            inner = p[1:-1]
            if not inner:
                raise ValueError(f"Malformed path segment: {p}")
            # Check for negative or non-integer
            if inner.startswith("-"):
                raise ValueError(f"Negative index not allowed: {p}")
            if not inner.isdigit():
                raise ValueError(f"Invalid index: {p}")
            idx = int(inner)
            steps.append(("index", idx))
        else:
            if "[" in p or "]" in p:
                raise ValueError(f"Malformed path segment: {p}")
            steps.append(("key", p))

    if not steps:
        raise ValueError("path is empty or malformed")

    if steps[0][0] != "key":
        raise ValueError("First step must be a key")

    # Deep copy to ensure immutability of input
    result = copy.deepcopy(obj)

    node = result

    # Navigate/create path up to the second-to-last step
    for i, (step_type, step_val) in enumerate(steps[:-1]):
        next_type, next_val = steps[i + 1]

        if step_type == "key":
            if not isinstance(node, dict):
                raise TypeError(f"Expected dict at path step, got {type(node).__name__}")

            if step_val not in node:
                # Create container based on next step
                if next_type == "index":
                    node[step_val] = []
                else:
                    node[step_val] = {}

            node = node[step_val]

        elif step_type == "index":
            if not isinstance(node, list):
                raise TypeError(f"Expected list at path step, got {type(node).__name__}")

            # Handle index bounds
            if step_val < 0:
                raise ValueError(f"Negative index not allowed: {step_val}")

            if step_val >= len(node):
                if step_val == len(node):
                    node.append(None)
                else:
                    # Pad with None
                    node.extend([None] * (step_val - len(node) + 1))

            if node[step_val] is None:
                # Create container based on next step
                if next_type == "index":
                    node[step_val] = []
                else:
                    node[step_val] = {}
            elif next_type == "index" and not isinstance(node[step_val], list):
                raise TypeError(f"Expected list at path step, got {type(node[step_val]).__name__}")
            elif next_type == "key" and not isinstance(node[step_val], dict):
                raise TypeError(f"Expected dict at path step, got {type(node[step_val]).__name__}")

            node = node[step_val]

    # Apply value at final step
    last_type, last_val = steps[-1]

    if last_type == "key":
        if not isinstance(node, dict):
            raise TypeError(f"Expected dict at final path step, got {type(node).__name__}")
        node[last_val] = value
    else:  # index
        if not isinstance(node, list):
            raise TypeError(f"Expected list at final path step, got {type(node).__name__}")

        if last_val < 0:
            raise ValueError(f"Negative index not allowed: {last_val}")

        if last_val >= len(node):
            if last_val == len(node):
                node.append(value)
            else:
                node.extend([None] * (last_val - len(node)))
                node.append(value)
        else:
            node[last_val] = value

    return result
```

