class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        # Clean expired lots and gather usable ones
        usable = []
        remaining = []
        for lot in self.lots.get(sku, []):
            if today > lot[0]:
                # Expired: drop
                continue
            if lot[1] > 0:
                usable.append(lot)
            # If lot[1] == 0, it's empty; don't keep it

        # Sort by expiry ascending, then by insertion order (stable sort preserves it)
        usable.sort(key=lambda x: x[0])

        # Recalculate usable total before taking
        usable_total = sum(lot[1] for lot in usable)
        if usable_total < qty:
            raise ValueError("insufficient")

        taken = []
        for lot in usable:
            if qty == 0:
                break
            n = min(qty, lot[1])
            lot[1] -= n
            qty -= n
            taken.append((lot[0], n))
            if lot[1] > 0:
                remaining.append(lot)
            # If lot[1] == 0, don't keep it

        # Append any unused usable lots back to remaining
        # Also preserve any lots that were not in usable (shouldn't happen after filter, but be safe)
        # Rebuild the list for this SKU
        self.lots[sku] = remaining + [lot for lot in self.lots.get(sku, []) if today <= lot[0] and lot[1] > 0 and lot not in usable]

        # Deduplicate: the above might have issues with identity. Let's rebuild cleanly.
        # Actually, simpler: rebuild from scratch using the filtered + updated lots.
        # We already updated 'usable' lots in place. Let's just collect all non-expired, non-empty lots.
        final_lots = []
        seen_ids = set()
        for lot in self.lots.get(sku, []):
            if id(lot) in seen_ids:
                continue
            if today <= lot[0] and lot[1] > 0:
                final_lots.append(lot)
                seen_ids.add(id(lot))
        self.lots[sku] = final_lots

        if qty:
            # This should not happen if usable_total check passed, but safety net
            raise ValueError("insufficient")

        return taken

    def stock(self, sku, today):
        total = 0
        if sku not in self.lots:
            return 0
        # Clean expired lots while calculating stock
        valid_lots = []
        for lot in self.lots[sku]:
            if today > lot[0]:
                # Expired: drop
                continue
            if lot[1] > 0:
                total += lot[1]
                valid_lots.append(lot)
        self.lots[sku] = valid_lots
        return total
