        # Use a list to hold the entry so we can remove by identity, not value
        # This handles the case where the same handler is subscribed multiple times
        def unsubscribe():
            if topic in self.subs:
                try:
                    self.subs[topic].remove(entry)
                except ValueError:
                    # Already unsubscribed; harmless as per spec
                    pass
                if not self.subs[topic]:
