        if topic not in self.subs:
            return 0

        # Snapshot the current list of handlers to avoid issues with modifications during iteration
        # Handlers subscribed during this emit won't be called (they're not in the snapshot)
        # Handlers unsubscribed during this emit won't be called if they haven't been reached yet
        snapshot = list(self.subs[topic])

        n = 0
        for _, h in snapshot:
            # Check if this handler is still subscribed before calling it
            # This handles the case where an earlier handler unsubscribed a later one
            if topic in self.subs and (0, h) in [(p, hdl) for p, hdl in self.subs[topic]]:
                # More precise check: verify the exact (priority, handler) pair still exists
                found = False
                for p, hdl in self.subs[topic]:
                    if hdl is h:
                        found = True
                        break
                if found:
                    h(*args)
                    n += 1
