class Bus:
    def __init__(self):
        self.subs = {}
        self._unsub_pending = {}
        self._sub_pending = {}
        self._emit_active = {}

    def on(self, topic, handler, priority=0):
        if topic not in self.subs:
            self.subs[topic] = []

        # If we are currently emitting, queue the subscription for later
        if self._emit_active.get(topic, False):
            if topic not in self._sub_pending:
                self._sub_pending[topic] = []
            self._sub_pending[topic].append((priority, handler))
        else:
            self.subs[topic].append((priority, handler))
            # Sort: higher priority first (descending), then by insertion order (stable)
            self.subs[topic].sort(key=lambda p: -p[0])

        def unsubscribe():
            # If called twice, do nothing (harmless)
            if topic not in self.subs:
                return
            if (priority, handler) not in self.subs[topic]:
                return

            if self._emit_active.get(topic, False):
                # If emitting, mark for removal after emit finishes
                if topic not in self._unsub_pending:
                    self._unsub_pending[topic] = []
                # Only add if not already marked
                if (priority, handler) not in self._unsub_pending[topic]:
                    self._unsub_pending[topic].append((priority, handler))
            else:
                self.subs[topic].remove((priority, handler))
                if not self.subs[topic]:
                    del self.subs[topic]

        return unsubscribe

    def emit(self, topic, *args):
        handlers = self.subs.get(topic, [])
        if not handlers:
            return 0

        self._emit_active[topic] = True
        n = 0

        # Create a snapshot of handlers to iterate over
        # We need to respect the "unsubscribe during emit" rule
        # So we iterate through the current list, but skip if marked for removal
        i = 0
        while i < len(handlers):
            priority, handler = handlers[i]

            # Check if this handler was marked for removal by an earlier handler in this same emit
            is_removed = False
            if topic in self._unsub_pending:
                if (priority, handler) in self._unsub_pending[topic]:
                    is_removed = True

            if not is_removed:
                handler(*args)
                n += 1
            i += 1

        self._emit_active[topic] = False

        # Process pending unsubscriptions
        if topic in self._unsub_pending:
            for priority, handler in self._unsub_pending[topic]:
                if topic in self.subs and (priority, handler) in self.subs[topic]:
                    self.subs[topic].remove((priority, handler))
            del self._unsub_pending[topic]
            if topic in self.subs and not self.subs[topic]:
                del self.subs[topic]

        # Process pending subscriptions
        if topic in self._sub_pending:
            for priority, handler in self._sub_pending[topic]:
                if topic not in self.subs:
                    self.subs[topic] = []
                self.subs[topic].append((priority, handler))
            # Re-sort after adding new subscriptions
            if topic in self.subs:
                self.subs[topic].sort(key=lambda p: -p[0])
            del self._sub_pending[topic]

        return n
