def group_averages(rows):
    sums = {}
    counts = {}
    first_seen = {}

    for name, value in rows:
        # Normalize key: strip whitespace and lowercase for grouping
        key = name.strip().lower()

        # Record the first spelling seen (with surrounding whitespace removed)
        if key not in first_seen:
            first_seen[key] = name.strip()

        # Initialize accumulators if this is the first time seeing this group
        if key not in sums:
            sums[key] = 0
            counts[key] = 0

        # Only process if value is not None
        if value is not None:
            sums[key] += value
            counts[key] += 1

    result = []
    for key in sums:
        label = first_seen[key]
        if counts[key] == 0:
            average = None
        else:
            average = sums[key] / counts[key]
        result.append((label, average))

    # Sort by the normalized key (case-insensitive) to ensure consistent ordering
    # We sort based on the key derived from the label (lowercase), 
    # but the output contains the original 'first_seen' label.
    result.sort(key=lambda x: x[0].lower())

    return result
