```python
def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from environment variables, overriding defaults.

    Args:
        defaults: A nested dict of default configuration values.
        env: A dict-like mapping of environment variable names to values.
        prefix: The prefix for environment variables (default: "APP_").

    Returns:
        A new config dict with defaults overridden by matching environment variables.
        The defaults object is not modified.

    Rules:
        - Only variables starting with `prefix` are considered.
        - The part after the prefix is lowercased and split by double underscores (`__`)
          to form the path. A single underscore is part of the key name.
        - The raw string is converted to the type of the default value.
        - Bool: accepts 1/true/yes/on and 0/false/no/off (case-insensitive).
        - Int/Float: parsed normally; invalid strings raise ValueError.
        - Other types: remain as strings.
        - Variables without the prefix or paths not in defaults are ignored.
    """
    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [deep_copy(item) for item in obj]
        else:
            return obj

    def parse_bool(raw):
        val = raw.lower().strip()
        if val in ("1", "true", "yes", "on"):
            return True
        elif val in ("0", "false", "no", "off"):
            return False
        else:
            raise ValueError(f"Invalid boolean value: {raw!r}")

    def convert_value(raw, default_val):
        target_type = type(default_val)
        if target_type is bool:
            return parse_bool(raw)
        elif target_type is int:
            return int(raw)
        elif target_type is float:
            return float(raw)
        else:
            # For strings or any other type, keep as string
            return raw

    def set_nested(node, path, value):
        for key in path[:-1]:
            if key not in node or not isinstance(node[key], dict):
                return  # Path does not exist, ignore
            node = node[key]
        if path[-1] in node:
            node[path[-1]] = value

    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue
        suffix = k[len(prefix):]
        # Split by double underscore for nesting; single underscore is part of the key
        path = suffix.lower().split("__")

        # Traverse to find the default value to determine type and validate path
        node = cfg
        valid_path = True
        for p in path:
            if p not in node or not isinstance(node, dict):
                valid_path = False
                break
            if p == path[-1]:
                break
            node = node[p]

        if not valid_path or path[-1] not in node:
            continue  # Ignore unknown paths

        try:
            converted = convert_value(raw, node[path[-1]])
            set_nested(cfg, path, converted)
        except (ValueError, TypeError):
            raise ValueError(f"Cannot convert {raw!r} to {type(node[path[-1]]).__name__} for path {'.'.join(path)}")

