import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parentheses. Reject unknown chars.
    token_pattern = r"\d+\.?\d*|\.\d+|[-+*/^()]"
    matches = re.findall(token_pattern, s)
    reconstructed = "".join(matches)
    # Remove spaces from original to check if anything non-space/non-token remains
    stripped = s.replace(" ", "")
    if stripped != reconstructed:
        raise ValueError("Invalid characters in expression")

    if not matches:
        raise ValueError("Empty expression")

    toks = matches
    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            if op == "/" and r == 0:
                raise ZeroDivisionError("division by zero")
            v = v * r if op == "*" else v / r
        return v

    def unary():
        t = peek()
        if t in ("+", "-"):
            take()
            if t == "-":
                return -unary()
            else:
                return +unary()
        return power()

    def power():
        v = atom()
        while peek() == "^":
            take()
            # Right-associative: exponent is a unary expression (allows -2^2 -> -(2^2))
            exp = unary()
            v = v ** exp
        return v

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("Unbalanced parentheses")
            take()
            return v
        if t in ("+", "-", "*", "/", "^", ")"):
            raise ValueError("Missing operand")
        take()
        return float(t)

    result = expr()
    if peek() is not None:
        raise ValueError("Unexpected trailing characters")
    return result
