        v = atom()
        if peek() == "^":
            take()
            # Right-associative: exponent is unary (allows -2^2 -> -(2^2))
            exp = unary()
            v = v ** exp
        return v

    def atom():
        t = peek()
        if t == "(":
            take()
            v = expr()
            expect(")")
            return v
        if t in ("+", "-", "*", "/", "^", ")"):
            raise ValueError("Missing operand")
