import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parentheses. Ignore spaces.
    tokens = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c in "+-*/^()":
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            has_dot = (c == '.')
            while j < len(s):
                ch = s[j]
                if ch.isdigit():
                    j += 1
                elif ch == '.' and not has_dot:
                    has_dot = True
                    j += 1
                else:
                    break
            tokens.append(s[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {c}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return t

    def expect_number():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t in "+-*/^()":
            raise ValueError(f"Unexpected operator: {t}")
        # Must be a number
        take()
        return float(t)

    def expr():
        # + and - (left to right), lowest precedence
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            if op == "+":
                v = v + r
            else:
                v = v - r
        return v

    def term():
        # * and / (left to right)
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            if op == "*":
                v = v * r
            else:
                if r == 0:
                    raise ZeroDivisionError("division by zero")
                v = v / r
        return v

    def unary():
        # unary + and -
        if peek() == "+":
            take()
            return unary()
        if peek() == "-":
            take()
            return -unary()
        return power()

    def power():
        # ^ (right-associative), tighter than unary
        base = atom()
        if peek() == "^":
            take()
            exp = unary()  # exponent may carry a sign; right-assoc handled by recursion
            return base ** exp
        return base

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            take()
            return v
        if t in "+-*/^)":
            raise ValueError(f"Unexpected token: {t}")
        # Must be a number
        take()
        try:
            return float(t)
        except ValueError:
            raise ValueError(f"Invalid number: {t}")

    result = expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing content")
    return result
