            _, exp = self.d[key]
            if now >= exp:
                del self.d[key]
                return True
        return False

    def _cleanup_expired(self, now):
        """Remove all expired entries."""
        expired_keys = [k for k, (_, exp) in self.d.items() if now >= exp]
        for k in expired_keys:
            del self.d[k]

    def get(self, key, now):
        if key not in self.d:
            return None
        v, exp = self.d[key]
        if now >= exp:
            del self.d[key]
            return None
        # Move to end to mark as most recently used
        self.d.move_to_end(key)
        return v

    def put(self, key, value, now):
        if self.cap <= 0:
            return

        # If key exists, update it (restarts TTL, moves to end)
        if key in self.d:
            self.d[key] = (value, now + self.ttl)
            self.d.move_to_end(key)
            return

        # New key: first drop expired entries
        self._cleanup_expired(now)

        # If still at capacity, evict LRU (oldest) entry
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)

        self.d[key] = (value, now + self.ttl)

    def size(self, now):
        self._cleanup_expired(now)
        return len(self.d)
