def parse_csv(text, delimiter=","):
    if not text:
        return []

    rows = []
    i = 0
    n = len(text)

    while i < n:
        # Skip empty lines outside quotes (but only if we're at the start of a line)
        # Check if current position is start of line and line is empty
        line_start = i
        if i < n and text[i] == '\r':
            i += 1
        if i < n and text[i] == '\n':
            i += 1
            # This was an empty line (just line terminator), skip it
            continue

        row = []
        while True:
            field = []
            quoted = False

            # Check if field starts with quote
            if i < n and text[i] == '"':
                quoted = True
                i += 1  # consume opening quote

                # Parse quoted field
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Escaped quote ""
                            field.append('"')
                            i += 2
                        else:
                            # End of quoted field
                            i += 1  # consume closing quote
                            break
                    else:
                        field.append(text[i])
                        i += 1
                else:
                    # Reached end without closing quote
                    raise ValueError("Unterminated quote")
            else:
                # Parse unquoted field
                while i < n:
                    if text[i] == '"' or text[i] == '\r' or text[i] == '\n':
                        if text[i] == '"' or text[i] == delimiter:
                            # In unquoted field, quote is literal, delimiter ends field
                            if text[i] == delimiter:
                                break
                            else:
                                field.append(text[i])
                                i += 1
                        else:
                            # \r or \n ends unquoted field and row
                            break
                    elif text[i] == delimiter:
                        break
                    else:
                        field.append(text[i])
                        i += 1

            row.append(''.join(field))

            # Check what comes after the field
            if i >= n:
                break

            if text[i] == delimiter:
                i += 1  # consume delimiter, continue to next field
                # If delimiter is at end of text, we need an empty field
                if i >= n:
                    row.append('')
                    break
            elif text[i] == '\r':
                i += 1
                if i < n and text[i] == '\n':
                    i += 1
                break
            elif text[i] == '\n':
                i += 1
                break
            else:
                # Should not reach here in normal parsing
                break

        # Only add row if it's not an empty line (but keep rows with empty fields)
        # A line with just "" produces a row with one empty string field
        # Completely empty lines are already skipped above
        if row or (i > line_start):
            rows.append(row)

        # Check if we're at end after line terminator
        if i >= n:
            break

    return rows
