def set_path(obj, path, value):
    """
    Returns a new structure where the location named by path holds value.
    obj and everything reachable from it is left untouched (deep copy semantics for mutable parts).

    Rules:
    - Path: dot-separated keys with optional list indexes (e.g., "a.b[2].c", "items[0]").
    - Missing dict keys are created as dicts.
    - Missing containers: dict if next step is key, list if next step is index.
    - Index == len(list): appends.
    - Index > len(list): pads with None up to that index.
    - Type mismatch (key on list/scalar, index on dict/scalar): raises TypeError.
    - Empty or malformed path: raises ValueError.
    - First step must be a key; obj must be a dict.
    """

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("Path must be a non-empty string")

    # Validate path format before processing
    # Check for leading/trailing dots, double dots, invalid brackets
    if path.startswith('.') or path.endswith('.'):
        raise ValueError("Path cannot start or end with a dot")

    if '..' in path:
        raise ValueError("Path cannot contain empty segments (double dots)")

    # Parse path into steps
    # We need to handle "a.b[2].c" -> ['a', 'b', '[2]', 'c']
    # But also "a[0].b" -> ['a', '[0]', 'b']

    steps = []
    current = ""
    i = 0
    while i < len(path):
        char = path[i]
        if char == '.':
            if current:
                steps.append(current)
                current = ""
            # Skip the dot
        elif char == '[':
            if current:
                steps.append(current)
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '[':  # Nested brackets not allowed
                    raise ValueError("Malformed path: nested brackets")
                j += 1
            if j >= len(path):
                raise ValueError("Malformed path: unclosed bracket")
            bracket_content = path[i+1:j]
            # Validate bracket content: must be non-negative integer
            if not bracket_content:
                raise ValueError("Malformed path: empty index")
            if not bracket_content.isdigit():
                raise ValueError("Malformed path: invalid index")
            steps.append(f"[{bracket_content}]")
            i = j  # Move to closing bracket, will be incremented at end of loop
        else:
            current += char
        i += 1

    if current:
        steps.append(current)

    if not steps:
        raise ValueError("Path is empty or malformed")

    # First step must be a key (not an index)
    if steps[0].startswith('['):
        raise ValueError("First step must be a key")

    # Deep copy function for our specific needs (dicts and lists only for this context)
    def deep_copy(item):
        if isinstance(item, dict):
            return {k: deep_copy(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [deep_copy(v) for v in item]
        else:
            return item

    # Start with a deep copy of the original object
    result = deep_copy(obj)

    # Navigate and build the structure
    node = result

    # Process all steps except the last one
    for idx, step in enumerate(steps[:-1]):
        next_step = steps[idx + 1]
        is_next_index = next_step.startswith('[')

        if step.startswith('['):
            # Index step
            index = int(step[1:-1])

            if not isinstance(node, list):
                raise TypeError(f"Expected list for index step, got {type(node).__name__}")

            # Handle index bounds
            if index > len(node):
                # Pad with None
                node.extend([None] * (index - len(node)))
            elif index == len(node):
                # Append new container
                if is_next_index:
                    node.append([])
                else:
                    node.append({})

            # Move to the indexed element
            if node[index] is None:
                if is_next_index:
                    node[index] = []
                else:
                    node[index] = {}

            node = node[index]

        else:
            # Key step
            key = step

            if not isinstance(node, dict):
                raise TypeError(f"Expected dict for key step, got {type(node).__name__}")

            if key not in node:
                # Create missing container
                if is_next_index:
                    node[key] = []
                else:
                    node[key] = {}

            node = node[key]

    # Handle the last step (set the value)
    last_step = steps[-1]

    if last_step.startswith('['):
        index = int(last_step[1:-1])

        if not isinstance(node, list):
            raise TypeError(f"Expected list for final index step, got {type(node).__name__}")

        if index > len(node):
            node.extend([None] * (index - len(node)))
        elif index == len(node):
            node.append(value)
            return result

        node[index] = value
    else:
        key = last_step

        if not isinstance(node, dict):
            raise TypeError(f"Expected dict for final key step, got {type(node).__name__}")

        node[key] = value

    return result
