                # Create missing container based on next step
                if next_type == "index":
                    node[step_value] = []
                else:
                    node[step_value] = {}
            node = node[step_value]
        else:  # step_type == "index"
            if not isinstance(node, list):
                raise TypeError("Cannot use index step on non-list")
            if step_value >= len(node):
                # Pad list with None up to the index
                while len(node) <= step_value:
                    node.append(None)
            if node[step_value] is None:
                # Create missing container based on next step
                if next_type == "index":
                    node[step_value] = []
                else:
                    node[step_value] = {}
            node = node[step_value]

    # Set the final value
    last_type, last_value = parts[-1]
    if last_type == "key":
        if not isinstance(node, dict):
            raise TypeError("Cannot use key step on non-dict")
        node[last_value] = value
    else:  # last_type == "index"
        if not isinstance(node, list):
            raise TypeError("Cannot use index step on non-list")
        if last_value >= len(node):
            # Pad list with None up to the index, then append value
            while len(node) < last_value:
                node.append(None)
            node.append(value)
        else:
            node[last_value] = value

