class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def _clean_and_sort(self, sku, today):
        """Remove expired lots and return sorted usable lots for the given SKU."""
        if sku not in self.lots:
            return []

        usable_lots = []
        for lot in self.lots[sku]:
            expires, qty = lot
            # Lot is usable if today <= expires. Drop if today > expires.
            if today <= expires and qty > 0:
                usable_lots.append(lot)

        # Sort by expiry date (ascending), then by original insertion order.
        # Since we append to the list in order, stable sort preserves insertion order for ties.
        usable_lots.sort(key=lambda x: x[0])

        # Update the stored lots to only include usable ones (dropping expired/empty)
        self.lots[sku] = usable_lots
        return usable_lots

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        usable_lots = self._clean_and_sort(sku, today)

        if sum(lot[1] for lot in usable_lots) < qty:
            raise ValueError("insufficient")

        taken = []
        remaining_qty = qty

        for lot in usable_lots:
            if remaining_qty == 0:
                break

            n = min(remaining_qty, lot[1])
            lot[1] -= n
            remaining_qty -= n
            taken.append((lot[0], n))

        if remaining_qty > 0:
            # This should not happen if the check above is correct, but for safety
            raise ValueError("insufficient")

        return taken

    def stock(self, sku, today):
        usable_lots = self._clean_and_sort(sku, today)
        return sum(lot[1] for lot in usable_lots)
