            if not index_str.isdigit():
                raise ValueError(f"Malformed path: non-numeric index '{index_str}' at position {i}")
            if index_str.startswith("0") and len(index_str) > 1:
                # Allow "0" but not "01", "007", etc.
                raise ValueError(f"Malformed path: index with leading zeros '{index_str}' at position {i}")
            parts.append(("index", int(index_str)))
            i = j
        elif ch == "]":
            raise ValueError(f"Malformed path: unexpected ']' at position {i}")
        else:
            current += ch
        i += 1

    if current:
        parts.append(("key", current))

    if not parts:
        raise ValueError("Path must contain at least one step")

    if parts[0][0] != "key":
        raise ValueError("First step must be a key")

    def deep_copy(node):
        """Create a deep copy that shares no mutable parts with the original."""
        if isinstance(node, dict):
            return {k: deep_copy(v) for k, v in node.items()}
        elif isinstance(node, list):
            return [deep_copy(item) for item in node]
        else:
            return node

    # Start with a deep copy
    result = deep_copy(obj)

    # Navigate to the parent of the target location
    current_node = result
    for step_type, step_value in parts[:-1]:
        if step_type == "key":
            if not isinstance(current_node, dict):
                raise TypeError(f"Expected dict at path step, got {type(current_node).__name__}")
            if step_value not in current_node:
                # Determine what to create based on next step
                next_type, _ = parts[parts.index((step_type, step_value)) + 1] if (step_type, step_value) in parts else ("key", None)
                # Actually, we need to look ahead properly
                idx = parts.index((step_type, step_value))
                if idx + 1 < len(parts):
                    next_step_type, _ = parts[idx + 1]
                    if next_step_type == "key":
                        current_node[step_value] = {}
                    else:
                        current_node[step_value] = []
                else:
                    current_node[step_value] = {}
            current_node = current_node[step_value]
        else:  # index
            if not isinstance(current_node, list):
                raise TypeError(f"Expected list at path step, got {type(current_node).__name__}")
            if step_value >= len(current_node):
                # Pad with None up to the index
                current_node.extend([None] * (step_value - len(current_node) + 1))
            if current_node[step_value] is None:
                # Determine what to create based on next step
                idx = parts.index((step_type, step_value))
                if idx + 1 < len(parts):
                    next_step_type, _ = parts[idx + 1]
                    if next_step_type == "key":
                        current_node[step_value] = {}
                    else:
                        current_node[step_value] = []
                else:
                    current_node[step_value] = {}
            current_node = current_node[step_value]

    # Set the final value
    last_type, last_value = parts[-1]
    if last_type == "key":
        if not isinstance(current_node, dict):
            raise TypeError(f"Expected dict at final path step, got {type(current_node).__name__}")
        current_node[last_value] = value
    else:  # index
        if not isinstance(current_node, list):
            raise TypeError(f"Expected list at final path step, got {type(current_node).__name__}")
        if last_value >= len(current_node):
            current_node.extend([None] * (last_value - len(current_node) + 1))
        current_node[last_value] = value

    return result
