class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        # Clean expired lots and gather usable ones
        usable = []
        if sku in self.lots:
            remaining_lots = []
            for lot in self.lots[sku]:
                if lot[1] <= 0:
                    continue
                if today > lot[0]:
                    # Expired, drop it
                    continue
                remaining_lots.append(lot)
                usable.append(lot)
            self.lots[sku] = remaining_lots

        # Sort usable lots: earliest expiry first, then earliest added (original order)
        # Since we preserved original order in the list, stable sort by expiry only is enough
        usable.sort(key=lambda l: l[0])

        # Check if we have enough stock
        total_usable = sum(lot[1] for lot in usable)
        if total_usable < qty:
            raise ValueError("insufficient")

        taken = []
        remaining_qty = qty

        for lot in usable:
            if remaining_qty == 0:
                break
            n = min(remaining_qty, lot[1])
            lot[1] -= n
            remaining_qty -= n
            taken.append((lot[0], n))

        return taken

    def stock(self, sku, today):
        if sku not in self.lots:
            return 0
        total = 0
        # Clean expired lots while computing stock
        remaining_lots = []
        for lot in self.lots[sku]:
            if lot[1] <= 0:
                continue
            if today > lot[0]:
                # Expired, drop it
                continue
            remaining_lots.append(lot)
            total += lot[1]
        self.lots[sku] = remaining_lots
        return total
