def set_path(obj, path, value):
    """
    Returns a new structure where the location named by path holds value.
    obj and everything reachable from it is left untouched (deep copy semantics).

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing containers: dict if next step is key, list if next step is index.
    - Index == len(list) appends; index > len(list) pads with None.
    - TypeError if existing value has wrong type for next step.
    - ValueError if path is empty, malformed, or has invalid syntax.
    - First step must be a key; obj must be a dict.
    """
    import copy

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before parsing
    if path.startswith('.') or path.startswith('['):
        raise ValueError("path must start with a key")

    if '..' in path:
        raise ValueError("path contains empty key")

    if path.endswith('.'):
        raise ValueError("path ends with empty key")

    # Parse path into tokens
    tokens = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError("empty key in path")
            tokens.append(('key', current))
            current = ""
        elif ch == '[':
            if current != "":
                tokens.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j >= len(path):
                raise ValueError("unclosed bracket in path")
            index_str = path[i+1:j]
            if index_str == "":
                raise ValueError("empty index in path")
            if index_str.startswith('-'):
                raise ValueError("negative index not allowed")
            try:
                idx = int(index_str)
            except ValueError:
                raise ValueError("invalid index: " + index_str)
            tokens.append(('index', idx))
            i = j  # will be incremented below
        else:
            current += ch
        i += 1

    if current != "":
        tokens.append(('key', current))

    if not tokens:
        raise ValueError("path is empty or malformed")

    if tokens[0][0] != 'key':
        raise ValueError("first step must be a key")

    # Deep copy the object to avoid mutating the original
    result = copy.deepcopy(obj)

    # Navigate and build the structure
    node = result

    for i in range(len(tokens) - 1):
        tok_type, tok_val = tokens[i]
        next_type, _ = tokens[i + 1]

        if tok_type == 'key':
            if not isinstance(node, dict):
                raise TypeError("expected dict at path segment")
            if tok_val not in node:
                # Create appropriate container based on next step
                if next_type == 'key':
                    node[tok_val] = {}
                else:
                    node[tok_val] = []
            node = node[tok_val]
            if next_type == 'index' and not isinstance(node, list):
                raise TypeError("expected list for index operation")
            if next_type == 'key' and not isinstance(node, dict):
                raise TypeError("expected dict for key operation")
        else:  # index
            if not isinstance(node, list):
                raise TypeError("expected list at path segment")
            idx = tok_val
            if idx < 0 or idx > len(node):
                raise IndexError("index out of range")
            if idx == len(node):
                # Append or pad based on next step
                if next_type == 'key':
                    node.append({})
                else:
                    node.append([])
            elif idx < len(node):
                if node[idx] is None:
                    # Initialize None slot based on next step
                    if next_type == 'key':
                        node[idx] = {}
                    else:
                        node[idx] = []
                elif next_type == 'key' and not isinstance(node[idx], dict):
                    raise TypeError("expected dict for key operation")
                elif next_type == 'index' and not isinstance(node[idx], list):
                    raise TypeError("expected list for index operation")
            node = node[idx]

    # Set the final value
    last_type, last_val = tokens[-1]
    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError("expected dict at final path segment")
        node[last_val] = value
    else:  # index
        if not isinstance(node, list):
            raise TypeError("expected list at final path segment")
        idx = last_val
        if idx < 0:
            raise IndexError("negative index not allowed")
        if idx > len(node):
            # Pad with None up to idx - 1, then set value at idx
            while len(node) <= idx:
                node.append(None)
        elif idx == len(node):
            node.append(value)
        else:
            node[idx] = value

    return result
```

The bug has two parts:
1. `get_profile` returns the cached dict directly, so callers mutating the returned dict (including nested dicts) mutate the cache and subsequent reads.
2. `update_profile` pops the cache using `str(uid)` but stores/looks up using `uid` (an int), so the cache is never invalidated; subsequent `get_profile` calls return the stale cached value.

Fix:
- Deep-copy the profile on both load and return so callers cannot mutate the cache or the DB state.
- Invalidate the cache with the same key type used for storage (`uid`), and ensure the cached value is a fresh deep copy on read-after-write.
- Ensure the first `get_profile` after an `update_profile` performs a DB read (by invalidating the cache), and repeats without further changes do not.

