The bugs are:
1. `receive` uses `vis < now` instead of `vis <= now`, so a message visible at `now=0` is skipped.
2. `receive` increments delivery count before checking the max-delivery limit, causing poison messages to be delivered 4 times and never moved to `dead`.
3. `ack` and `extend` lack the "held" check: they must verify the message exists AND is currently held (`now < visible_at`), returning `False` otherwise; `ack` must not delete unheld/expired/unknown messages.
4. `extend` adds `extra` to the old `visible_at` instead of setting `visible_at = now + extra`.
5. `receive` does not move messages that have reached 3 deliveries to `q.dead`.

```python
class VisQueue:
    def __init__(self, timeout):
        self.timeout = timeout
        self.items = {}
        self.dead = []
        self.n = 0

    def send(self, payload):
        self.n += 1
        self.items[self.n] = [payload, 0, 0]
        return self.n

    def receive(self, now):
        for mid in sorted(self.items):
            payload, vis, cnt = self.items[mid]
            if vis <= now:
                if cnt >= 3:
                    self.dead.append((mid, payload))
                    del self.items[mid]
                    continue
                self.items[mid] = [payload, now + self.timeout, cnt + 1]
                return mid, payload
        return None

    def ack(self, mid, now):
        if mid not in self.items:
            return False
        payload, vis, cnt = self.items[mid]
        if not (now < vis):
            return False
        del self.items[mid]
        return True

    def extend(self, mid, now, extra):
        if mid not in self.items:
            return False
        payload, vis, cnt = self.items[mid]
        if not (now < vis):
            return False
        self.items[mid][1] = now + extra
        return True
