def group_averages(rows):
    """
    Group rows by name (case-insensitive, ignoring surrounding whitespace),
    compute averages of non-None values, and return sorted by label (case-insensitive).

    - Names differing only in case or surrounding whitespace are grouped together.
    - The label used is the first spelling seen, with surrounding whitespace stripped.
    - None values are ignored (not counted, not treated as zero).
    - Groups with no valid readings have average None.
    - Result is sorted by label ignoring case.
    """
    sums = {}
    counts = {}
    labels = {}  # maps normalized key -> first seen label (stripped)

    for name, value in rows:
        key = name.strip().lower()
        if key not in labels:
            labels[key] = name.strip()

        if value is not None:
            sums[key] = sums.get(key, 0) + value
            counts[key] = counts.get(key, 0) + 1
        else:
            # Ensure the group exists even if all values are None
            if key not in sums:
                sums[key] = 0
            if key not in counts:
                counts[key] = 0

    result = []
    for key in sums:
        label = labels[key]
        count = counts[key]
        if count == 0:
            average = None
        else:
            average = sums[key] / count
        result.append((label, average))

    return sorted(result, key=lambda x: x[0].lower())
