        for key in keys[:-1]:
            if key not in node or not isinstance(node[key], dict):
                return  # Path does not exist, ignore
            node = node[key]
        if keys[-1] not in node:
            return  # Final key does not exist, ignore
        target = node[keys[-1]]
        node[keys[-1]] = _convert_value(value, target)

