        # The spec says: "a double underscore separates nesting levels"
        # and "a single underscore is part of the key name".
        # However, the observed bug says "keys containing an underscore break the loader".
        # The original code did .split("_") which splits on every underscore.
        # We need to split on "__" only.

        path = path_part.lower().split("__")

