def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from environment variables, overriding defaults.

    Rules:
    - Variables must start with `prefix` (default "APP_").
    - The part after the prefix is lowercased and split by "__" (double underscore)
      to form the nesting path. A single underscore is part of the key name.
    - The raw string is converted to the type of the default value.
    - Bool: accepts 1/true/yes/on and 0/false/no/off (case-insensitive).
    - Int/Float: parsed numerically.
    - Other: stays string.
    - Variables without the prefix or paths not in defaults are ignored.
    - The defaults object is not modified.
    """
    import copy

    def parse_value(target_type, raw):
        if target_type is bool:
            v = raw.lower()
            if v in ("1", "true", "yes", "on"):
                return True
            if v in ("0", "false", "no", "off"):
                return False
            raise ValueError(f"Invalid boolean value: {raw}")
        return target_type(raw)

    def build_nested_dict(keys, value):
        if len(keys) == 1:
            return {keys[0]: value}
        return {keys[0]: build_nested_dict(keys[1:], value)}

    def merge_into(base, override):
        result = copy.deepcopy(base)
        for k, v in override.items():
            if k in result and isinstance(result[k], dict) and isinstance(v, dict):
                result[k] = merge_into(result[k], v)
            else:
                result[k] = copy.deepcopy(v)
        return result

    cfg = copy.deepcopy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue
        path_key = k[len(prefix):]
        path = path_key.lower().split("__")

        # Traverse to check if path exists in defaults
        node = defaults
        valid_path = True
        for p in path:
            if isinstance(node, dict) and p in node:
                node = node[p]
            else:
                valid_path = False
                break

        if not valid_path:
            continue

        try:
            converted = parse_value(type(node), raw)
        except (ValueError, TypeError):
            continue

        # Build nested override dict
        override_dict = build_nested_dict(path, converted)
        cfg = merge_into(cfg, override_dict)

    return cfg
