import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parens. Reject unknown chars.
    raw_tokens = re.findall(r"\d+\.?\d*|\.\d+|[-+*/^()]|\S", s)
    if not raw_tokens:
        raise ValueError("Empty expression")

    toks = []
    for t in raw_tokens:
        if re.match(r"\d+\.?\d*|\.\d+", t):
            toks.append(("NUM", float(t)))
        elif t in "+-*/^()":
            toks.append(("OP", t))
        else:
            raise ValueError(f"Invalid character: {t}")

    if not toks:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expect_num():
        t = peek()
        if t is None or t[0] != "NUM":
            raise ValueError("Missing operand")
        return take()[1]

    def expr():
        v = term()
        while True:
            t = peek()
            if t is None or t[0] != "OP" or t[1] not in ("+", "-"):
                break
            op = take()[1]
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while True:
            t = peek()
            if t is None or t[0] != "OP" or t[1] not in ("*", "/"):
                break
            op = take()[1]
            r = unary()
            if op == "/":
                if r == 0:
                    raise ZeroDivisionError("division by zero")
                v = v / r
            else:
                v = v * r
        return v

    def unary():
        t = peek()
        if t is not None and t[0] == "OP" and t[1] in ("+", "-"):
            op = take()[1]
            val = unary()
            return -val if op == "-" else val
        return power()

    def power():
        v = atom()
        while True:
            t = peek()
            if t is None or t[0] != "OP" or t[1] != "^":
                break
            take()  # consume '^'
            # Right-associative: exponent is a unary (so it can start with +/-)
            e = unary()
            v = v ** e
        return v

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t[0] == "NUM":
            return take()[1]
        if t[0] == "OP" and t[1] == "(":
            take()  # consume '('
            val = expr()
            t = peek()
            if t is None or t[0] != "OP" or t[1] != ")":
                raise ValueError("Unbalanced parentheses")
            take()  # consume ')'
            return val
        raise ValueError("Invalid expression")

    result = expr()
    if peek() is not None:
        raise ValueError("Invalid expression")
    return result
