        while peek() in ("*", "/"):
            op = take()
            r = unary()
            if op == "/" and r == 0:
                raise ZeroDivisionError("Division by zero")
            v = v * r if op == "*" else v / r
        return v

    def unary():
        if peek() == "+":
            take()
            return unary()
        if peek() == "-":
            take()
            return -unary()
        return power()

    def power():
        v = atom()
        if peek() == "^":
            take()
            # Right-associative: exponent itself can have a sign (via unary)
            exp = unary()
            v = v ** exp
        return v

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
