def set_path(obj, path, value):
    """
    Returns a new structure where the location named by path holds value.
    The original obj and everything reachable from it is left untouched.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path:
        raise ValueError("Path cannot be empty")

    # Validate path format before processing
    if path.startswith(".") or path.endswith("."):
        raise ValueError(f"Malformed path: {path}")
    if ".." in path:
        raise ValueError(f"Malformed path: {path}")

    # Check for invalid index formats like [-1], [x], or unclosed [
    import re
    bracket_contents = re.findall(r'\[(.*?)\]', path)
    for content in bracket_contents:
        if not content:
            raise ValueError(f"Malformed path: empty brackets in {path}")
        if not content.isdigit():
            raise ValueError(f"Malformed path: invalid index '{content}' in {path}")
        if content.startswith('-') or (content != '0' and content.startswith('0')):
             # Actually, standard int() handles '0' fine, but leading zeros like '01' might be ambiguous. 
             # The spec says "a[-1]", "a[x]" are bad. "01" is technically a digit string. 
             # Let's stick to strict digit check which allows "0", "1", "10".
             pass 
        if content.startswith('-'):
            raise ValueError(f"Malformed path: negative index '{content}' in {path}")

    # Deep copy helper to ensure no shared mutable state
    def deep_copy(item):
        if isinstance(item, dict):
            return {k: deep_copy(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [deep_copy(v) for v in item]
        else:
            return item

    # Start with a deep copy of the original object
    result = deep_copy(obj)

    # Parse path into steps
    # We need to handle "a.b[2].c" -> ['a', 'b', '[2]', 'c'] roughly, but carefully.
    # The strategy: split by dots, but keep brackets attached to the previous key if no dot?
    # Actually, the spec says "dot-separated keys with optional list indexes".
    # Example: "a.b[2].c". 
    # Let's normalize: replace '[' with '.[' so split('.') works nicely?
    # "a.b[2].c" -> "a.b.[2].c" -> ['a', 'b', '[2]', 'c']
    # Edge case: "items[0]" -> "items.[0]" -> ['items', '[0]']

    normalized_path = path.replace("[", ".[")
    parts = normalized_path.split(".")

    # Filter out empty strings that might result from leading/trailing dots (already checked) or double dots (already checked)
    parts = [p for p in parts if p]

    if not parts:
        raise ValueError("Path resolved to no parts")

    # The first step must be a key (dict access), not an index
    if parts[0].startswith("["):
        raise ValueError("The first step must be a key")

    node = result

    # Iterate through all parts except the last one to navigate/create structure
    for i in range(len(parts) - 1):
        part = parts[i]
        next_part = parts[i+1]

        if part.startswith("["):
            # Index step
            idx = int(part[1:-1])
            if not isinstance(node, list):
                raise TypeError(f"Expected list for index step, got {type(node).__name__}")

            # Handle padding or appending
            if idx == len(node):
                node.append(None)
            elif idx > len(node):
                # Pad with None up to idx
                node.extend([None] * (idx - len(node)))

            # Ensure the next node exists and is of correct type
            if node[idx] is None:
                if next_part.startswith("["):
                    node[idx] = []
                else:
                    node[idx] = {}

            node = node[idx]

        else:
            # Key step
            if not isinstance(node, dict):
                raise TypeError(f"Expected dict for key step, got {type(node).__name__}")

            if part not in node:
                # Create missing container based on next step
                if next_part.startswith("["):
                    node[part] = []
                else:
                    node[part] = {}

            node = node[part]

    # Handle the last part (assignment)
    last = parts[-1]
    if last.startswith("["):
        idx = int(last[1:-1])
        if not isinstance(node, list):
            raise TypeError(f"Expected list for final index step, got {type(node).__name__}")

        if idx == len(node):
            node.append(value)
        elif idx > len(node):
            node.extend([None] * (idx - len(node)))
            node[idx] = value
        else:
            node[idx] = value
    else:
        if not isinstance(node, dict):
            raise TypeError(f"Expected dict for final key step, got {type(node).__name__}")
        node[last] = value

    return result
