    current = ""
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current:
                # It's a key
                steps.append(('key', current))
                current = ""
            elif i + 1 < len(path) and path[i+1] == '.':
                raise ValueError(f"Malformed path: empty key at position {i}")
            # else: leading dot or consecutive dots handled
