            inner = part[1:-1]
            if not inner.isdigit():
                raise ValueError(f"Malformed path: invalid index '{inner}'")
            steps.append(('index', int(inner)))
        else:
            # Key step
            if "[" in part:
                raise ValueError(f"Malformed path: unexpected bracket in '{part}'")
            steps.append(('key', part))

    # Traverse and build
    current = root
    for i in range(len(steps) - 1):
        step_type, step_val = steps[i]
