def set_path(obj, path, value):
    """
    Set a value at a nested path in a structure, returning a new structure.

    The original obj and everything reachable from it must be left untouched.
    The result shares no mutable parts with obj.

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts
    - Missing containers: dict when next step is key, list when next step is index
    - Index equal to list length appends
    - Index larger than list length pads with None up to that index
    - Wrong type for next step raises TypeError
    - Empty or malformed path raises ValueError
    - First step must be a key, obj must be a dict
    """

    def deep_copy_structure(o):
        """Create a deep copy without sharing mutable parts."""
        if isinstance(o, dict):
            return {k: deep_copy_structure(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy_structure(item) for item in o]
        else:
            return o

    def parse_path(path_str):
        """Parse path string into list of (type, key/index) tuples."""
        if not path_str:
            raise ValueError("Path cannot be empty")

        if path_str.startswith('.'):
            raise ValueError("Path cannot start with '.'")

        if '..' in path_str:
            raise ValueError("Path cannot contain '..'")

        parts = []
        current = ""
        i = 0

        while i < len(path_str):
            char = path_str[i]

            if char == '.':
                if current:
                    parts.append(('key', current))
                    current = ""
                elif i == 0 or path_str[i-1] == '.':
                    raise ValueError("Empty key in path")
                i += 1
                continue

            if char == '[':
                if current:
                    parts.append(('key', current))
                    current = ""

                # Find closing bracket
                j = i + 1
                while j < len(path_str) and path_str[j] != ']':
                    j += 1

                if j >= len(path_str):
                    raise ValueError("Unclosed bracket in path")

                index_str = path_str[i+1:j]

                # Validate index: must be non-negative integer
                if not index_str:
                    raise ValueError("Empty index in path")

                if index_str.startswith('-'):
                    raise ValueError("Negative indexes not allowed")

                try:
                    index_val = int(index_str)
                except ValueError:
                    raise ValueError(f"Invalid index: {index_str}")

                parts.append(('index', index_val))
                i = j + 1
                continue

            if char == ']':
                raise ValueError("Unmatched closing bracket")

            current += char
            i += 1

        if current:
            parts.append(('key', current))

        # Validate: first step must be a key
        if parts and parts[0][0] != 'key':
            raise ValueError("First step must be a key")

        return parts

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    parts = parse_path(path)

    if not parts:
        raise ValueError("Path cannot be empty")

    # Deep copy the original structure
    result = deep_copy_structure(obj)

    # Navigate and build the new structure
    current = result

    for i, (step_type, step_key) in enumerate(parts[:-1]):
        next_type, next_key = parts[i + 1]

        if step_type == 'key':
            if not isinstance(current, dict):
                raise TypeError(f"Expected dict at path, got {type(current).__name__}")

            if step_key not in current:
                # Create appropriate container based on next step
                if next_type == 'key':
                    current[step_key] = {}
                else:
                    current[step_key] = []

            current = current[step_key]

            # Type check for next step
            if next_type == 'key' and not isinstance(current, dict):
                raise TypeError(f"Expected dict at path, got {type(current).__name__}")
            elif next_type == 'index' and not isinstance(current, list):
                raise TypeError(f"Expected list at path, got {type(current).__name__}")

        else:  # step_type == 'index'
            if not isinstance(current, list):
                raise TypeError(f"Expected list at path, got {type(current).__name__}")

            if step_key < 0:
                raise ValueError("Negative indexes not allowed")

            # Extend list if needed
            while len(current) <= step_key:
                current.append(None)

            if current[step_key] is None:
                # Create appropriate container based on next step
                if next_type == 'key':
                    current[step_key] = {}
                else:
                    current[step_key] = []

            current = current[step_key]

            # Type check for next step
            if next_type == 'key' and not isinstance(current, dict):
                raise TypeError(f"Expected dict at path, got {type(current).__name__}")
            elif next_type == 'index' and not isinstance(current, list):
                raise TypeError(f"Expected list at path, got {type(current).__name__}")

    # Set the final value
    last_type, last_key = parts[-1]

    if last_type == 'key':
        if not isinstance(current, dict):
            raise TypeError(f"Expected dict at path, got {type(current).__name__}")
        current[last_key] = value
    else:  # last_type == 'index'
        if not isinstance(current, list):
            raise TypeError(f"Expected list at path, got {type(current).__name__}")

        if last_key < 0:
            raise ValueError("Negative indexes not allowed")

        # Extend list if needed (append or pad)
        while len(current) <= last_key:
            current.append(None)

        current[last_key] = value

    return result
