def set_path(obj, path, value):
    """
    Returns a new structure with the value set at the given path.
    The original obj is left untouched (deep copy semantics for the path).
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")
    if not path:
        raise ValueError("path cannot be empty")

    # Validate path format before processing
    if path.startswith(".") or path.endswith(".") or ".." in path:
        raise ValueError("path is malformed")

    # Parse path into steps
    # We split by '.' but need to handle brackets carefully
    # Strategy: replace '[' with '.[' then split, but validate brackets first
    temp = path.replace("[", ".[")
    parts = temp.split(".")

    # Filter out empty strings that might result from splitting
    steps = []
    for p in parts:
        if not p:
            continue
        if p.startswith("["):
            # Index step
            if not p.endswith("]"):
                raise ValueError("malformed index in path")
            inner = p[1:-1]
            if not inner.isdigit() or (len(inner) > 1 and inner[0] == '0'):
                # Allow "0" but not "01", and no negative numbers
                if inner == "0":
                    pass
                elif inner.isdigit() and inner[0] != '0':
                    pass
                else:
                    raise ValueError("invalid index format")
            idx = int(inner)
            if idx < 0:
                raise ValueError("negative indices not supported")
            steps.append(("index", idx))
        else:
            # Key step
            if "[" in p or "]" in p:
                raise ValueError("malformed key in path")
            steps.append(("key", p))

    if not steps:
        raise ValueError("path is empty or malformed")

    if steps[0][0] != "key":
        raise ValueError("first step must be a key")

    # Deep copy the parts of the structure we will traverse/modify
    # We need to create new containers along the path, sharing only untouched branches

    def deep_copy_container(item, stop_at=None):
        """Deep copy only the containers we need to modify."""
        if isinstance(item, dict):
            return {k: v for k, v in item.items()}
        elif isinstance(item, list):
            return [x for x in item]
        return item

    # Build the new structure by copying the path
    if not steps:
        return obj

    # Start with a shallow copy of the root dict
    result = {k: v for k, v in obj.items()}
    current = result

    # Navigate and copy containers along the path
    for i, (step_type, step_val) in enumerate(steps[:-1]):
        next_step_type, next_step_val = steps[i + 1]

        if step_type == "key":
            if not isinstance(current, dict):
                raise TypeError("expected dict at path segment")

            if step_val not in current:
                # Create new container based on next step
                if next_step_type == "index":
                    current[step_val] = []
                else:
                    current[step_val] = {}

            # Check type compatibility
            existing = current[step_val]
            if next_step_type == "index":
                if not isinstance(existing, list):
                    raise TypeError("expected list at path segment")
            else:
                if not isinstance(existing, dict):
                    raise TypeError("expected dict at path segment")

            # Move to next level, ensuring we have a mutable copy if it was shared
            if isinstance(current[step_val], dict):
                current[step_val] = {k: v for k, v in current[step_val].items()}
            elif isinstance(current[step_val], list):
                current[step_val] = [x for x in current[step_val]]

            current = current[step_val]

        else:  # step_type == "index"
            if not isinstance(current, list):
                raise TypeError("expected list at path segment")

            idx = step_val
            if idx > len(current):
                raise IndexError("index out of range")

            if idx == len(current):
                # This shouldn't happen in navigation (only at final step for append)
                # But if we're navigating through, the list must exist
                raise IndexError("index out of range for navigation")

            existing = current[idx]
            next_step_type, _ = steps[i + 1]

            # Check type compatibility for next step
            if next_step_type == "index":
                if existing is not None and not isinstance(existing, list):
                    raise TypeError("expected list at path segment")
            else:
                if existing is not None and not isinstance(existing, dict):
                    raise TypeError("expected dict at path segment")

            # Ensure we have a mutable copy
            if isinstance(existing, dict):
                current[idx] = {k: v for k, v in existing.items()}
            elif isinstance(existing, list):
                current[idx] = [x for x in existing]
            elif existing is None:
                # Create the container
                if next_step_type == "index":
                    current[idx] = []
                else:
                    current[idx] = {}

            current = current[idx]

    # Set the final value
    final_step_type, final_step_val = steps[-1]

    if final_step_type == "key":
        if not isinstance(current, dict):
            raise TypeError("expected dict at final path segment")
        current[final_step_val] = value
    else:  # index
        if not isinstance(current, list):
            raise TypeError("expected list at final path segment")

        idx = final_step_val
        if idx > len(current):
            # Pad with None
            while len(current) < idx:
                current.append(None)
            current.append(value)
        elif idx == len(current):
            current.append(value)
        else:
            current[idx] = value

    return result
