        new_lots = []
        seen_refs = set()
        for expires, amount, lot_ref in usable:
            if lot_ref[1] > 0 and lot_ref not in seen_refs:
                new_lots.append(lot_ref)
                seen_refs.add(lot_ref)
        # Add back any lots that were not in usable because they had 0 amount but were not expired (edge case)
        for lot in self.lots.get(sku, []):
            expires, amount = lot
