class ProfileService:
    def __init__(self, db):
        self.db = db
        self.cache = {}
        self.db_reads = 0

    def _load(self, uid):
        self.db_reads += 1
        return dict(self.db[uid])

    def _deep_copy(self, d):
        """Return a deep copy of a dict containing only dicts and primitives."""
        if not isinstance(d, dict):
            return d
        result = {}
        for k, v in d.items():
            if isinstance(v, dict):
                result[k] = self._deep_copy(v)
            else:
                result[k] = v
        return result

    def get_profile(self, uid):
        if uid not in self.cache:
            self.cache[uid] = self._load(uid)
        # Return a deep copy so callers can mutate it without affecting the store
        return self._deep_copy(self.cache[uid])

    def update_profile(self, uid, changes):
        if uid not in self.db:
            raise KeyError(uid)
        # Load fresh from DB to ensure we have the latest stored version
        profile = self._load(uid)
        # Merge changes: new keys added, existing keys replaced, nested dicts replaced as a whole
        profile.update(changes)
        # Persist to DB
        self.db[uid] = profile
        # Update cache with the new merged profile (so subsequent reads don't hit DB)
        self.cache[uid] = profile
        # Note: We do NOT pop the cache entry; we update it to avoid unnecessary DB reads on next get_profile.
        # The original code incorrectly popped the cache using str(uid) instead of uid, and then
        # forced a DB read on next get_profile, but more importantly, it didn't update the cache
        # with the new profile, causing stale data to be served if the cache wasn't properly invalidated.
        # However, the real bug described is that get_profile sometimes shows old profile until restart.
        # This happens because:
        # 1. The cache was being popped with str(uid) but stored with uid (int), so pop failed.
        # 2. Even if pop worked, the next get_profile would reload from DB, but if the DB write failed
        #    or was delayed, it would still show old data. But the main issue is the cache key mismatch.
