def wrap(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")

    # Split text into paragraphs by blank lines
    paragraphs = text.split('\n\n')
    result_lines = []

    for para in paragraphs:
        # Split paragraph into words (collapsing all whitespace)
        words = para.split()
        if not words:
            continue

        lines = []
        line = ""

        for w in words:
            # Handle words longer than width by breaking them
            while len(w) > width:
                # If current line has content, save it first
                if line:
                    lines.append(line)
                    line = ""
                # Take a chunk of size width from the word
                lines.append(w[:width])
                w = w[width:]

            # Now w fits in width (or is empty)
            if not w:
                continue

            if line == "":
                line = w
            elif len(line) + 1 + len(w) <= width:
                line = line + " " + w
            else:
                lines.append(line)
                line = w

        if line:
            lines.append(line)

        if lines:
            if result_lines:
                result_lines.append("")
            result_lines.extend(lines)

    return result_lines
