        if k <= 0:
            return []
        node = self.root
        # Fix: normalize prefix to lowercase for case-insensitive matching
        for ch in prefix.lower():
            if ch not in node:
                return []
            node = node[ch]
        found = []

        def walk(n, acc):
            for key, child in n.items():
                if key == "$":
                    found.append((child, acc))
                else:
                    walk(child, acc + key)

        walk(node, prefix.lower())
        # Fix: sort by weight descending, then by word ascending (alphabetical)
        # Tuple comparison: (weight, word). We want high weight first, so negate weight.
        found.sort(key=lambda x: (-x[0], x[1]))
        # Fix: return exactly k items (slice [:k]), not k-1
        return [w for _, w in found[:k]]

