import re


def evaluate(s):
    # Validate input: must not be empty, must not contain unknown characters
    if not s or not s.strip():
        raise ValueError("Empty input")

    # Check for invalid characters before tokenizing
    stripped = s.replace(" ", "")
    if not stripped:
        raise ValueError("Empty input")

    valid_chars = set("0123456789.+-*/^()")
    for ch in stripped:
        if ch not in valid_chars:
            raise ValueError(f"Invalid character: {ch}")

    # Tokenize: numbers (including decimals) and operators
    toks = re.findall(r"\d+\.?\d*|\.\d+|[-+*/^()]", s)

    if not toks:
        raise ValueError("No valid tokens found")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = factor()
        while peek() in ("*", "/"):
            op = take()
            r = factor()
            v = v * r if op == "*" else v / r
        return v

    def factor():
        # Handle unary + and - with highest precedence for the sign itself
        # but lower than exponentiation base binding
        if peek() == "+":
            take()
            return factor()
        if peek() == "-":
            take()
            return -factor()
        return power()

    def power():
        v = atom()
        # Right-associative exponentiation
        if peek() == "^":
            take()
            exp = factor()  # exponent may carry a sign, and ^ is right-associative
            v = v ** exp
        return v

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("Unbalanced parentheses: missing ')'")
            take()
            return v
        if t in ("+", "-", "*", "/", "^", ")"):
            raise ValueError(f"Unexpected token: {t}")
        take()
        # Validate number format
        try:
            return float(t)
        except ValueError:
            raise ValueError(f"Invalid number: {t}")

    result = expr()

    if pos != len(toks):
        raise ValueError(f"Unexpected token after expression: {toks[pos]}")

    return result
