```python
def set_path(obj, path, value):
    """
    Set a value at a dotted/bracketed path in a nested structure, returning a
    new structure that shares no mutable parts with the original.

    Rules:
    - path: dot-separated keys with optional list indexes, e.g. "a.b[2].c".
    - Missing dict keys are created as dicts.
    - Missing list positions are created; index == len appends; index > len
      pads with None up to that index.
    - If an existing value has the wrong type for the next step, raise TypeError.
    - Empty or malformed paths raise ValueError.
    - The first step must be a key and obj must be a dict.
    - obj and everything reachable from it is left untouched (deep copy on write).
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")
    if not path:
        raise ValueError("path cannot be empty")

    # Validate and tokenize the path
    # We cannot have leading '.', trailing '.', empty parts like 'a..b',
    # negative indexes, non-numeric indexes, or unclosed brackets.
    if path.startswith(".") or path.endswith("."):
        raise ValueError("path cannot start or end with a dot")
    if ".." in path:
        raise ValueError("path contains empty segment")

    tokens = []
    i = 0
    n = len(path)
    current_key = ""

    while i < n:
        ch = path[i]
        if ch == ".":
            if current_key:
                tokens.append(("key", current_key))
                current_key = ""
            i += 1
        elif ch == "[":
            if current_key:
                tokens.append(("key", current_key))
                current_key = ""
            # Find closing bracket
            j = i + 1
            while j < n and path[j] != "]":
                if path[j] == "[":  # nested bracket not allowed
                    raise ValueError("malformed path: nested brackets")
                j += 1
            if j == n:
                raise ValueError("malformed path: unclosed bracket")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError("malformed path: empty index")
            if index_str.startswith("-"):
                raise ValueError("malformed path: negative index not allowed")
            if not index_str.isdigit():
                raise ValueError("malformed path: non-numeric index")
            tokens.append(("index", int(index_str)))
            i = j + 1
        elif ch == "]":
            raise ValueError("malformed path: unmatched closing bracket")
        else:
            current_key += ch
            i += 1

    if current_key:
        tokens.append(("key", current_key))

    if not tokens:
        raise ValueError("path cannot be empty")

    # First step must be a key
    if tokens[0][0] != "key":
        raise ValueError("first step must be a key")

    # Deep copy helper for dicts and lists only (shallow for immutables)
    def deep_copy_container(x):
        if isinstance(x, dict):
            return {k: v for k, v in x.items()}
        elif isinstance(x, list):
            return [item for item in x]
        else:
            return x

    # Build a new structure step by step
    result = {}
    node = result

    # We will reconstruct the path, copying only what we traverse
    # Strategy: walk the original obj and the new result in parallel,
    # copying nodes as we go, until we reach the target location.

    # But simpler: recursively clone only the path we need to modify.
    # We'll do an iterative approach: for each step except the last,
    # ensure the container exists in the new structure, copying from old if needed.

    current_old = obj
    current_new = result

    for idx, (step_type, step_val) in enumerate(tokens[:-1]):
        next_type, next_val = tokens[idx + 1]

        if step_type == "key":
            if not isinstance(current_new, dict):
                raise TypeError("expected dict at key step")
            if not isinstance(current_old, dict):
                # Old doesn't have this key or isn't a dict -> create new container
                if next_type == "index":
                    current_new[step_val] = []
                else:
                    current_new[step_val] = {}
                current_old = None
            else:
                if step_val not in current_old:
                    # Key missing in old -> create new container
                    if next_type == "index":
                        current_new[step_val] = []
                    else:
                        current_new[step_val] = {}
                    current_old = None
                else:
                    old_val = current_old[step_val]
                    if next_type == "index" and not isinstance(old_val, list):
                        raise TypeError("expected list for index step")
                    if next_type == "key" and not isinstance(old_val, dict):
                        raise TypeError("expected dict for key step")
                    # Copy the container
                    current_new[step_val] = deep_copy_container(old_val)
                    current_old = old_val
            current_new = current_new[step_val]

        elif step_type == "index":
            if not isinstance(current_new, list):
                raise TypeError("expected list at index step")
            if current_old is None or not isinstance(current_old, list):
                # Old is not a list or doesn't exist -> we need to ensure index exists
                # Pad with None up to step_val
                while len(current_new) <= step_val:
                    current_new.append(None)
                current_old = None
            else:
                # Old is a list
                if step_val >= len(current_old):
                    # Index beyond old list -> pad new list, copy what exists
                    for k in range(len(current_old)):
                        if len(current_new) <= k:
                            current_new.append(deep_copy_container(current_old[k]))
                    while len(current_new) <= step_val:
                        current_new.append(None)
                    current_old = None
                else:
                    old_val = current_old[step_val]
                    if next_type == "index" and not isinstance(old_val, list):
                        raise TypeError("expected list for index step")
                    if next_type == "key" and not isinstance(old_val, dict):
                        raise TypeError("expected dict for key step")
                    # Ensure new list is long enough
                    while len(current_new) <= step_val:
                        current_new.append(None)
                    current_new[step_val] = deep_copy_container(old_val)
                    current_old = old_val
            current_new = current_new[step_val]

    # Handle the last step
    last_type, last_val = tokens[-1]
    if last_type == "key":
        if not isinstance(current_new, dict):
            raise TypeError("expected dict at final key step")
        current_new[last_val] = value
    elif last_type == "index":
        if not isinstance(current_new, list):
            raise TypeError("expected list at final index step")
        # Pad if necessary
        while len(current_new) <= last_val:
            current_new.append(None)
        current_new[last_val] = value

    return result
