The bug analysis based on the ticket and source:

1.  **Lines stop one character short**: The condition `len(line) + 1 + len(w) < width` uses strict inequality (`<`). It should be `<=` to allow a line to reach exactly `width` characters when adding a word (plus the space).
2.  **Empty line before exact fit / Long words overflow**: The current logic blindly appends `line` (which might be empty if it was just flushed) and sets `line = w`. It doesn't handle:
    *   Flushing an empty line unnecessarily.
    *   Breaking words longer than `width`.
    *   Starting a new line correctly after a break.
3.  **Paragraph breaks lost**: `text.split()` collapses all whitespace, including newlines, losing paragraph structure. We need to split by paragraphs first (blank lines) and then wrap each paragraph.
4.  **`width < 1` raises ValueError**: This check is missing.
5.  **Empty/blank text gives `[]`**: The current logic might return `['']` or similar if not handled carefully after the loop.

Here is the corrected module:

```python
def wrap(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")

    if not text or not text.strip():
        return []

    # Split text into paragraphs (separated by one or more blank lines)
    # A blank line is a line with no non-whitespace characters.
    # We split by double newlines or more, but need to be careful with mixed whitespace.
    # Strategy: Split by lines, group non-empty lines into paragraphs.
    raw_lines = text.splitlines()

    paragraphs = []
    current_para_lines = []

    for line in raw_lines:
        if line.strip() == "":
            if current_para_lines:
                paragraphs.append(" ".join(current_para_lines))
                current_para_lines = []
            # Else: consecutive blank lines, just ignore extra ones
        else:
            # Collapse whitespace within the line as per "runs collapse to one space"
            # Actually, the spec says "Words are separated by any whitespace (runs collapse to one space)"
            # This usually applies to the whole text processing. 
            # Let's collect words for the paragraph.
            current_para_lines.extend(line.split())

    if current_para_lines:
        paragraphs.append(" ".join(current_para_lines))

    if not paragraphs:
        return []

    result_lines = []

    for para in paragraphs:
        # Wrap this paragraph
        words = para.split() # Already collapsed spaces by join/split logic above? 
        # Wait, " ".join(current_para_lines) creates a string with single spaces.
        # But if we did extend with split(), we have a list of words.
        # Let's re-extract words to be safe and clear.
        words = para.split()

        if not words:
            continue

        current_line = ""

        for word in words:
            if not current_line:
                # Start of a line
                if len(word) <= width:
                    current_line = word
                else:
                    # Word longer than width: break it
                    while len(word) > width:
                        result_lines.append(word[:width])
                        word = word[width:]
                    current_line = word # Remainder starts new line
            else:
                # Try to add to current line
                if len(current_line) + 1 + len(word) <= width:
                    current_line += " " + word
                else:
                    # Flush current line
                    result_lines.append(current_line)
                    # Process the new word (might be long)
                    if len(word) <= width:
                        current_line = word
                    else:
                        # Break long word
                        while len(word) > width:
                            result_lines.append(word[:width])
                            word = word[width:]
                        current_line = word

        if current_line:
            result_lines.append(current_line)

    # Insert exactly one "" between paragraphs in the result?
    # The spec says: "the result has exactly one "" between paragraphs."
    # This usually means in the list of lines, there is an empty string separating them.
    # But wait, if I process paragraph by paragraph and append to result_lines,
    # I need to insert "" between the blocks of lines belonging to different paragraphs.

    final_result = []
    para_blocks = []

    # Re-do the logic to capture blocks per paragraph clearly
    raw_lines = text.splitlines()
    paragraphs_words = []
    current_words = []

    for line in raw_lines:
        if line.strip() == "":
            if current_words:
                paragraphs_words.append(current_words)
                current_words = []
        else:
            current_words.extend(line.split())

    if current_words:
        paragraphs_words.append(current_words)

    if not paragraphs_words:
        return []

    final_result = []
    for i, words in enumerate(paragraphs_words):
        if i > 0:
            final_result.append("") # Exactly one "" between paragraphs

        current_line = ""
        for word in words:
            if not current_line:
                if len(word) <= width:
                    current_line = word
                else:
                    while len(word) > width:
                        final_result.append(word[:width])
                        word = word[width:]
                    current_line = word
            else:
                if len(current_line) + 1 + len(word) <= width:
                    current_line += " " + word
                else:
                    final_result.append(current_line)
                    if len(word) <= width:
                        current_line = word
                    else:
                        while len(word) > width:
                            final_result.append(word[:width])
                            word = word[width:]
                        current_line = word

        if current_line:
            final_result.append(current_line)

    return final_result
