import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parens. Ignore whitespace.
    # Raise ValueError if any non-whitespace, non-token character exists.
    raw_tokens = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c in "+-*/^()":
            raw_tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            has_dot = (c == '.')
            while j < len(s):
                ch = s[j]
                if ch.isdigit():
                    j += 1
                elif ch == '.' and not has_dot:
                    has_dot = True
                    j += 1
                else:
                    break
            raw_tokens.append(s[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {c!r}")

    if not raw_tokens:
        raise ValueError("Empty expression")

    # Validate token sequence and parse with correct precedence:
    # Precedence (loosest to tightest): + - (L), * / (L), unary +/-, ^ (R).
    # Grammar:
    #   expr   -> term (('+' | '-') term)*
    #   term   -> power (('*' | '/') power)*
    #   power  -> unary ('^' power)?   # right-associative
    #   unary  -> ('+' | '-') unary | atom
    #   atom   -> NUMBER | '(' expr ')'
    #
    # Additional validation:
    #   - No two numbers in a row
    #   - No missing operands (e.g., "2 +", "(2", "2 3")
    #   - Balanced parentheses
    #   - Proper placement of unary vs binary operators

    toks = raw_tokens
    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return t

    def expect_number_or_paren_close():
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        if t == ')':
            return None  # signal to caller that we hit a closing paren
        if t in "+-*/^":
            raise ValueError(f"Unexpected operator: {t!r}")
        # Must be a number
        return take()

    def expr():
        v = term()
        while True:
            op = peek()
            if op not in ("+", "-"):
                break
            take()
            r = term()
            if op == "+":
                v = v + r
            else:
                v = v - r
        return v

    def term():
        v = power()
        while True:
            op = peek()
            if op not in ("*", "/"):
                break
            take()
            r = power()
            if op == "*":
                v = v * r
            else:
                if r == 0:
                    raise ZeroDivisionError("division by zero")
                v = v / r
        return v

    def power():
        # power -> unary ('^' power)?  (right-associative)
        v = unary()
        if peek() == "^":
            take()
            exp = power()  # right-recursive for right-associativity
            v = v ** exp
        return v

    def unary():
        t = peek()
        if t == "+":
            take()
            return unary()
        if t == "-":
            take()
            return -unary()
        return atom()

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        if t == "(":
            take()  # consume '('
            v = expr()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            take()  # consume ')'
            return v
        if t in "+-*/^)":
            raise ValueError(f"Unexpected token: {t!r}")
        # Must be a number
        num_str = take()
        try:
            return float(num_str)
        except ValueError:
            raise ValueError(f"Invalid number: {num_str!r}")

    result = expr()

    if pos != len(toks):
        raise ValueError(f"Unexpected token after expression: {toks[pos]!r}")

    return result
