def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.

    Rules:
    - Path is dot-separated keys with optional list indexes (e.g., "a.b[2].c").
    - Missing dict keys are created.
    - Missing container is dict if next step is key, list if next step is index.
    - Index == len(list) appends; index > len(list) pads with None.
    - Type mismatch (key on list/scalar, index on dict/scalar) raises TypeError.
    - Empty, malformed, or negative/index-non-integer paths raise ValueError.
    - First step must be a key; obj must be a dict.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")
    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate and parse path
    # We cannot simply split by '.' after replacing '[' because of edge cases.
    # We need to parse step by step to validate format and types.

    tokens = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError(f"Malformed path: empty segment at position {i}")
            tokens.append(('key', current))
            current = ""
        elif ch == '[':
            if current != "":
                tokens.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j == len(path):
                raise ValueError(f"Malformed path: unclosed bracket at position {i}")
            inner = path[i+1:j]
            if inner == "":
                raise ValueError(f"Malformed path: empty index at position {i}")
            if inner.startswith('-') or not inner.isdigit():
                raise ValueError(f"Malformed path: invalid index '{inner}' at position {i}")
            tokens.append(('index', int(inner)))
            i = j  # move to ']'
        else:
            current += ch
        i += 1

    if current != "":
        tokens.append(('key', current))

    if not tokens:
        raise ValueError("path must contain at least one step")

    if tokens[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Deep copy helper
    def deep_copy_structure(o):
        if isinstance(o, dict):
            return {k: deep_copy_structure(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy_structure(item) for item in o]
        else:
            return o

    # Start with a deep copy to ensure immutability of original
    result = deep_copy_structure(obj)

    node = result
    # Traverse all but the last token, creating missing containers as needed
    for idx in range(len(tokens) - 1):
        t_type, t_val = tokens[idx]
        next_type, _ = tokens[idx + 1]

        if t_type == 'key':
            if not isinstance(node, dict):
                raise TypeError(f"Expected dict at path step, got {type(node).__name__}")
            if t_val not in node:
                # Create missing container based on next step
                if next_type == 'index':
                    node[t_val] = []
                else:
                    node[t_val] = {}
            node = node[t_val]
        elif t_type == 'index':
            if not isinstance(node, list):
                raise TypeError(f"Expected list at path step, got {type(node).__name__}")
            if t_val < 0 or t_val > len(node):
                # According to spec: index == len appends, index > len pads with None
                if t_val > len(node):
                    # Pad with None up to t_val - 1, then the target will be at t_val
                    node.extend([None] * (t_val - len(node)))
                # If t_val == len, we will append later or now if it's the last step
                # But here we are in intermediate steps, so we must ensure the element exists
                if t_val == len(node):
                    # For intermediate steps, if next is key, we need a dict; if index, a list
                    if next_type == 'index':
                        node.append([])
                    else:
                        node.append({})
                else:
                    # t_val < len(node), just access
                    pass
            node = node[t_val]

    # Handle the last token
    last_type, last_val = tokens[-1]
    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError(f"Expected dict at final path step, got {type(node).__name__}")
        node[last_val] = value
    elif last_type == 'index':
        if not isinstance(node, list):
            raise TypeError(f"Expected list at final path step, got {type(node).__name__}")
        if last_val < 0:
            raise ValueError("Negative indices are not supported")
        if last_val > len(node):
            node.extend([None] * (last_val - len(node)))
            node.append(value)
        elif last_val == len(node):
            node.append(value)
        else:
            node[last_val] = value

    return result
