            return self.done[key]

        if amount <= 0:
            raise ValueError("amount")
        if src == dst:
            raise ValueError("src == dst")
        if src not in self.bal:
            raise KeyError(src)
        if dst not in self.bal:
            raise KeyError(dst)

        fee = max(1, amount // 100)
        total = amount + fee

        if self.bal[src] < total:
            result = False
        else:
            self.bal[src] -= total
            self.bal[dst] += amount
            result = True

        if key is not None:
            self.done[key] = result

        return result
