        raise ValueError("width must be >= 1")

    # Split into paragraphs by blank lines (one or more)
    paragraphs = text.split('\n\n')
    result = []

    for para in paragraphs:
        # Strip leading/trailing whitespace from the paragraph to handle extra newlines/spaces
        para = para.strip()
        if not para:
            continue

        words = para.split()
        if not words:
            continue

        lines = []
        current_line = ""

        for word in words:
            if not current_line:
                # Start a new line with the word (or piece of it)
                if len(word) <= width:
                    current_line = word
                else:
                    # Word is longer than width: cut it
                    # Take first 'width' chars for current line
                    current_line = word[:width]
                    lines.append(current_line)
                    # Remainder starts fresh
                    remainder = word[width:]
                    if remainder:
                        current_line = remainder
                    else:
                        current_line = ""
            else:
                # Try to add word to current line
                if len(current_line) + 1 + len(word) <= width:
                    current_line += " " + word
                else:
                    # Doesn't fit, push current line and start new one
                    lines.append(current_line)
                    # Now handle the word on the new line
                    if len(word) <= width:
                        current_line = word
                    else:
                        # Word longer than width: cut it
                        current_line = word[:width]
                        lines.append(current_line)
                        remainder = word[width:]
                        if remainder:
                            current_line = remainder
                        else:
                            current_line = ""

        if current_line:
            lines.append(current_line)

        result.extend(lines)
        result.append("")  # One blank line between paragraphs

    # Remove the trailing blank line if present
    if result and result[-1] == "":
        result.pop()

    return result
