from collections import deque


class RateWindow:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.events = deque()

    def allow(self, t):
        # First, remove expired events (those <= t - window)
        # An event at time e counts only while e > t - window
        cutoff = t - self.window
        while self.events and self.events[0] <= cutoff:
            self.events.popleft()

        # Check if we can allow this event
        if len(self.events) < self.limit:
            self.events.append(t)
            return True
        else:
            # Rejected - do not record the event
            return False

    def retry_after(self, t):
        if not self.events:
            return 0

        # Remove expired events first to get accurate count
        cutoff = t - self.window
        while self.events and self.events[0] <= cutoff:
            self.events.popleft()

        if not self.events:
            return 0

        if len(self.events) < self.limit:
            return 0

        # We're at capacity; the earliest event must expire before we can add another
        # The earliest event at self.events[0] expires when t > self.events[0] + self.window
        # So we need to wait until t = self.events[0] + self.window + epsilon
        # retry_after should be the time until self.events[0] + self.window
        wait = self.events[0] + self.window - t
        return max(0, wait)
