The bug is that `fnmatch` does not support `**` (recursive glob) and treats `*` as matching `/`. The spec requires `*` to stop at `/`, `**` to match across `/`, and `**/` to match zero or more directories.

I will implement a custom matcher that:
1. Parses the pattern into tokens handling `**`, `*`, `?`, `[...]`, and escapes.
2. Implements recursive matching logic respecting the directory separator rules.

```python
import re


def glob_match(pattern, path):
    """
    Match a glob pattern against a path.

    Rules:
    - '*' matches any run of characters except '/' (including none).
    - '?' matches exactly one character except '/'.
    - '**' matches any characters including '/'.
    - '**/' matches zero or more whole directories.
    - '[abc]', '[a-c]', '[!abc]' match character classes (never '/').
    - Backslash escapes the next character.
    - Everything else is literal and case-sensitive.
    - Leading dot is not special.
    """

    def parse_pattern(pat):
        """Parse pattern into a list of tokens."""
        tokens = []
        i = 0
        n = len(pat)

        while i < n:
            c = pat[i]

            if c == '\\':
                # Escape: next char is literal
                if i + 1 < n:
                    tokens.append(('LITERAL', pat[i+1]))
                    i += 2
                else:
                    tokens.append(('LITERAL', '\\'))
                    i += 1
            elif c == '*':
                # Check for **
                if i + 1 < n and pat[i+1] == '*':
                    # Check for **/
                    if i + 2 < n and pat[i+2] == '/':
                        tokens.append(('DOUBLE_STAR_SLASH',))
                        i += 3
                    else:
                        tokens.append(('DOUBLE_STAR',))
                        i += 2
                else:
                    tokens.append(('STAR',))
                    i += 1
            elif c == '?':
                tokens.append(('QUESTION',))
                i += 1
            elif c == '[':
                # Parse character class
                j = i + 1
                if j < n and pat[j] == '!':
                    j += 1
                if j < n and pat[j] == ']':
                    j += 1
                while j < n and pat[j] != ']':
                    j += 1
                if j >= n:
                    # No closing bracket, treat as literal
                    tokens.append(('LITERAL', '['))
                    i += 1
                else:
                    class_str = pat[i+1:j]
                    negated = False
                    if class_str.startswith('!'):
                        negated = True
                        class_str = class_str[1:]
                    # Also handle leading ] in class
                    chars = set()
                    k = 0
                    # If first char is ], it's part of the set
                    if k < len(class_str) and class_str[k] == ']':
                        chars.add(']')
                        k += 1
                    while k < len(class_str):
                        if k + 2 < len(class_str) and class_str[k+1] == '-' and class_str[k+2] != ']':
                            # Range
                            start = class_str[k]
                            end = class_str[k+2]
                            for code in range(ord(start), ord(end) + 1):
                                chars.add(chr(code))
                            k += 3
                        else:
                            chars.add(class_str[k])
                            k += 1
                    tokens.append(('CLASS', chars, negated))
                    i = j + 1
            else:
                tokens.append(('LITERAL', c))
                i += 1

        return tokens

    def match_tokens(tokens, t_idx, path, p_idx):
        """Recursively match tokens against path."""
        n_tokens = len(tokens)
        n_path = len(path)

        while t_idx < n_tokens:
            token = tokens[t_idx]
            kind = token[0]

            if kind == 'LITERAL':
                if p_idx >= n_path or path[p_idx] != token[1]:
                    return False
                p_idx += 1
                t_idx += 1
            elif kind == 'QUESTION':
                if p_idx >= n_path or path[p_idx] == '/':
                    return False
                p_idx += 1
                t_idx += 1
            elif kind == 'STAR':
                # Match any chars except '/'
                t_idx += 1
                # Try matching 0 or more non-slash chars
                while True:
                    if match_tokens(tokens, t_idx, path, p_idx):
                        return True
                    if p_idx >= n_path or path[p_idx] == '/':
                        break
                    p_idx += 1
                return False
            elif kind == 'DOUBLE_STAR':
                # Match anything including '/'
                t_idx += 1
                # Try matching from current position to end
                while True:
                    if match_tokens(tokens, t_idx, path, p_idx):
                        return True
                    if p_idx >= n_path:
                        break
                    p_idx += 1
                return False
            elif kind == 'DOUBLE_STAR_SLASH':
                # Match zero or more directories (including the slash)
                t_idx += 1
                # Option 1: match zero directories (skip this token, continue)
                if match_tokens(tokens, t_idx, path, p_idx):
                    return True
                # Option 2: match one or more chars until we find a slash, then recurse
                orig_p = p_idx
                while p_idx < n_path:
                    if path[p_idx] == '/':
                        p_idx += 1
                        if match_tokens(tokens, t_idx, path, p_idx):
                            return True
                        # Continue to try matching more directories
                    else:
                        p_idx += 1
                return False
            elif kind == 'CLASS':
                if p_idx >= n_path:
                    return False
                ch = path[p_idx]
                if ch == '/':
                    return False  # Class never matches '/'
                chars, negated = token[1], token[2]
                in_class = ch in chars
                if negated:
                    in_class = not in_class
                if not in_class:
                    return False
                p_idx += 1
                t_idx += 1
            else:
                # Unknown token type
                return False

        # All tokens consumed, check if path is also fully consumed
        return p_idx == n_path

    tokens = parse_pattern(pattern)
    return match_tokens(tokens, 0, path, 0)
