def group_averages(rows):
    sums = {}
    counts = {}
    first_seen = {}

    for name, value in rows:
        # Normalize the name: strip whitespace and convert to lowercase for grouping
        normalized = name.strip().lower()

        # Track the first original spelling (with whitespace stripped) for the label
        if normalized not in first_seen:
            first_seen[normalized] = name.strip()

        # Initialize accumulators if this is the first time seeing this group
        if normalized not in sums:
            sums[normalized] = 0
            counts[normalized] = 0

        # Only process if value is not None
        if value is not None:
            sums[normalized] += value
            counts[normalized] += 1

    result = []
    for normalized in sums:
        label = first_seen[normalized]
        count = counts[normalized]

        if count == 0:
            average = None
        else:
            average = sums[normalized] / count

        result.append((label, average))

    # Sort by the normalized name (case-insensitive), which corresponds to the group key
    # However, the requirement says "sorted by name ignoring case". 
    # Since our keys are already normalized (lowercase), sorting by the normalized key works.
    # But we need to return the list sorted. The iteration order over a dict is insertion order (Py3.7+),
    # so we must explicitly sort. We sort by the normalized key to ensure case-insensitive sorting.
    # We construct a temporary list of (normalized_key, label, average) to sort, then extract.

    unsorted_results = []
    for normalized in sums:
        label = first_seen[normalized]
        count = counts[normalized]
        if count == 0:
            average = None
        else:
            average = sums[normalized] / count
        unsorted_results.append((normalized, label, average))

    unsorted_results.sort(key=lambda x: x[0])

    return [(label, average) for (_, label, average) in unsorted_results]
