    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        suffix = k[len(prefix):]
        # Split only on double underscores for nesting, single underscores are part of the key
        # We need to reconstruct the path properly.
        # The spec says: "a double underscore separates nesting levels"
        # "a single underscore is part of the key name"
        # And "PATH is lower-cased"

        # Let's split by '__' first
        parts = suffix.split('__')
        path = [p.lower() for p in parts]

        # Traverse to check if path exists and to find the node
        node = cfg
        valid_path = True

        # Check if the path exists in the defaults structure
        for i, p in enumerate(path):
            if isinstance(node, dict) and p in node:
                if i == len(path) - 1:
                    # We reached the final key, ready to assign
                    break
                node = node[p]
            else:
                valid_path = False
                break

        if not valid_path:
            continue

        # Ensure we are assigning to a dict key that exists
        if not isinstance(node, dict) or path[-1] not in node:
            continue

        try:
            target_value = node[path[-1]]
            node[path[-1]] = _convert_value(raw, target_value)
        except ValueError:
            raise

