def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from defaults, overridden by environment variables.

    - Variables must start with `prefix`.
    - The suffix after the prefix is lowercased and split by double underscores `__`
      to form the path (e.g., APP_DB__MAX_CONNS -> ["db", "max_conns"]).
    - Single underscores within a key name are preserved.
    - Values are cast to the type of the default value.
    - Booleans accept: 1/true/yes/on (True) and 0/false/no/off (False), case-insensitive.
    - Unknown paths or variables without the prefix are ignored.
    - The defaults object is not modified.
    """
    def parse_bool(val):
        v = val.strip().lower()
        if v in ('1', 'true', 'yes', 'on'):
            return True
        if v in ('0', 'false', 'no', 'off'):
            return False
        raise ValueError(f"Invalid boolean value: {val}")

    def cast_value(value, target_type):
        if target_type is bool:
            return parse_bool(value)
        return target_type(value)

    # Deep copy defaults to avoid mutation
    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [deep_copy(item) for item in obj]
        return obj

    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Extract path: remove prefix, lowercase, split by double underscore
        suffix = k[len(prefix):]
        # Split by double underscore only; single underscores are part of the key
        path = suffix.lower().split("__")

        # Traverse to the parent node
        node = cfg
        valid_path = True
        for p in path[:-1]:
            if p not in node or not isinstance(node[p], dict):
                valid_path = False
                break
            node = node[p]

        if not valid_path:
            continue

        final_key = path[-1]
        if final_key not in node:
            continue

        try:
            target_type = type(node[final_key])
            node[final_key] = cast_value(raw, target_type)
        except (ValueError, TypeError):
            # Ignore variables that cannot be cast to the target type
            continue

    return cfg
```

The bug has four causes:
1. `dict(defaults)` is a shallow copy, so nested dicts are shared and mutated.
2. The path split uses `_` for everything, so `APP_DB__MAX_CONNS` splits into `["db", "", "max", "conns"]` instead of `["db", "max_conns"]`. Nesting is indicated by `__`, single `_` belongs to the key name.
3. Type conversion blindly calls `type(default)(raw)`, which fails for booleans (e.g., `"false"` becomes `bool("false") == True`) and doesn't validate unknown env vars against existing paths.
4. Missing validation that the path exists in defaults before assignment, causing crashes on unknown variables.

