def load_config(defaults, env, prefix="APP_"):
    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        return obj

    def parse_bool(raw):
        if raw.lower() in ("1", "true", "yes", "on"):
            return True
        if raw.lower() in ("0", "false", "no", "off"):
            return False
        raise ValueError(f"Invalid boolean value: {raw}")

    def get_at_path(obj, path):
        for p in path:
            if not isinstance(obj, dict) or p not in obj:
                return None
            obj = obj[p]
        return obj

    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Extract the path part after prefix
        path_part = k[len(prefix):]

        # Split by double underscore for nesting, single underscore stays in key names
        path = path_part.lower().split("__")

        # Check if path exists in defaults
        if get_at_path(defaults, path) is None:
            continue

        # Navigate to the parent node
        node = cfg
        for p in path[:-1]:
            node = node[p]

        # Get the default value to determine target type
        default_val = get_at_path(defaults, path)
        target_type = type(default_val)

        # Convert raw string to appropriate type
        if target_type is bool:
            converted = parse_bool(raw)
        elif target_type is int:
            converted = int(raw)
        elif target_type is float:
            converted = float(raw)
        else:
            converted = raw

        node[path[-1]] = converted

    return cfg
