import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parentheses.
    # Ignore whitespace; raise ValueError on unknown characters.
    raw_tokens = []
    i = 0
    while i < len(s):
        ch = s[i]
        if ch.isspace():
            i += 1
            continue
        if ch in "+-*/^()":
            raw_tokens.append(ch)
            i += 1
            continue
        if ch.isdigit() or ch == '.':
            j = i
            has_dot = (ch == '.')
            while j < len(s):
                c = s[j]
                if c.isdigit():
                    j += 1
                    continue
                if c == '.' and not has_dot:
                    has_dot = True
                    j += 1
                    continue
                break
            raw_tokens.append(s[i:j])
            i = j
            continue
        # Unknown character
        raise ValueError(f"Invalid character: {ch!r}")

    if not raw_tokens:
        raise ValueError("Empty expression")

    # Validate parentheses balance
    balance = 0
    for t in raw_tokens:
        if t == '(':
            balance += 1
        elif t == ')':
            balance -= 1
            if balance < 0:
                raise ValueError("Unbalanced parentheses")
    if balance != 0:
        raise ValueError("Unbalanced parentheses")

    # Pre-check for obvious syntax errors: two numbers in a row, missing operand
    # We'll do a deeper check during parsing, but catch some early.
    # Actually, the recursive descent will catch most; we just need to ensure
    # we don't silently accept garbage.

    toks = raw_tokens
    pos = 0
    n = len(toks)

    def peek():
        return toks[pos] if pos < n else None

    def take():
        nonlocal pos
        if pos >= n:
            raise ValueError("Unexpected end of expression")
        t = toks[pos]
        pos += 1
        return t

    def expect_number_or_paren_or_unary():
        # Helper to ensure we have something valid for an atom/unary start
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t in ('+', '-') or t == '(' or (t[0].isdigit() or t[0] == '.'):
            return True
        raise ValueError(f"Unexpected token: {t!r}")

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            # After binary operator, must have operand
            expect_number_or_paren_or_unary()
            r = term()
            if op == "+":
                v = v + r
            else:
                v = v - r
        return v

    def term():
        v = power()
        while peek() in ("*", "/"):
            op = take()
            expect_number_or_paren_or_unary()
            r = power()
            if op == "*":
                v = v * r
            else:
                if r == 0:
                    raise ZeroDivisionError("division by zero")
                v = v / r
        return v

    def power():
        # Right-associative: a ^ b ^ c = a ^ (b ^ c)
        v = atom()
        while peek() == "^":
            take()  # consume '^'
            expect_number_or_paren_or_unary()
            # For right associativity, we parse the rest as a power chain
            # But our loop is left-associative by default. Fix:
            # We need to parse the exponent as a full power expression.
            # Since we're in a while loop, we can instead do:
            # v = v ** power()  --> but that would be left-recursive if not careful.
            # Actually, the standard fix: parse base, then if '^', parse exponent as power() recursively.
            # Let's restructure slightly:
            exp = power()  # recursive call handles right-associativity
            v = v ** exp
        return v

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t == '+':
            take()
            return +atom()
        if t == '-':
            take()
            return -atom()
        if t == '(':
            take()  # consume '('
            v = expr()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            take()  # consume ')'
            return v
        # Must be a number
        if not (t[0].isdigit() or t[0] == '.'):
            raise ValueError(f"Unexpected token: {t!r}")
        take()
        try:
            return float(t)
        except ValueError:
            raise ValueError(f"Invalid number: {t!r}")

    result = expr()
    if pos != n:
        raise ValueError(f"Unexpected token: {toks[pos]!r}")
    return result
