import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parentheses.
    # Reject unknown characters or empty input early.
    if not s or not s.strip():
        raise ValueError("Empty input")

    token_pattern = r"\d+\.?\d*|\.\d+|[-+*/^()]|\s+"
    raw_tokens = re.findall(token_pattern, s)
    joined = "".join(raw_tokens)
    if len(joined) != len(s):
        # There were characters not matched (unknown chars)
        raise ValueError("Invalid characters in input")

    # Filter out whitespace tokens for parsing
    toks = [t for t in raw_tokens if not t.isspace()]
    if not toks:
        raise ValueError("Empty input")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return t

    def expect_number():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        # Check if it's a number
        if re.fullmatch(r"\d+\.?\d*|\.\d+", t):
            return take()
        else:
            raise ValueError(f"Expected number, got '{t}'")

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            if op == "/":
                if r == 0:
                    raise ZeroDivisionError("Division by zero")
            v = v * r if op == "*" else v / r
        return v

    def unary():
        # Handle unary + and -
        if peek() == "+":
            take()
            return unary()
        if peek() == "-":
            take()
            return -unary()
        return power()

    def power():
        # Base: could be a number or parenthesized expression
        base = atom()
        # Right-associative exponentiation
        if peek() == "^":
            take()
            # Exponent is unary (so -2^2 = -(2^2), but 2^-1 = 2^(-1))
            exp = unary()
            base = base ** exp
        return base

    def atom():
        t = peek()
        if t == "(":
            take()  # consume '('
            v = expr()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            take()  # consume ')'
            return v
        elif t is not None and re.fullmatch(r"\d+\.?\d*|\.\d+", t):
            return float(take())
        else:
            raise ValueError(f"Unexpected token: '{t}'")

    result = expr()
    if pos != len(toks):
        raise ValueError(f"Unexpected token after expression: '{toks[pos]}'")
    return result
