        self.d.move_to_end(key)
        return v

    def put(self, key, value, now):
        if self.cap <= 0:
            return
        exp = now + self.ttl
        if key in self.d:
            # Update existing key: replace value, restart TTL, move to end
            self.d[key] = (value, exp)
            self.d.move_to_end(key)
            return

        # New key: first drop expired entries
        self._cleanup_expired(now)

        # If still full, evict LRU (least recently used = first item)
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)

        self.d[key] = (value, exp)

    def size(self, now):
        # Count only live (non-expired) entries
        count = 0
        for _, exp in self.d.values():
            if now < exp:
                count += 1
        return count
