def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing containers for index steps are created as lists.
    - Index equal to list length appends.
    - Index larger than list length pads with None up to that index.
    - Type mismatch (key on list/scalar, index on dict/scalar) raises TypeError.
    - Empty or malformed paths raise ValueError.
    - First step must be a key, and obj must be a dict.
    """

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before processing
    # Check for leading/trailing dots, consecutive dots, invalid brackets
    if path.startswith('.') or path.endswith('.'):
        raise ValueError("path cannot start or end with a dot")

    if '..' in path:
        raise ValueError("path cannot contain consecutive dots")

    # Parse the path into steps
    # We need to handle cases like "a.b[2].c" -> ["a", "b", "[2]", "c"]
    # and "items[0]" -> ["items", "[0]"]

    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current:
                steps.append(current)
                current = ""
            # Skip the dot
        elif ch == '[':
            # Save any preceding key
            if current:
                steps.append(current)
                current = ""
            # Find the closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '[':
                    raise ValueError("nested brackets not allowed")
                j += 1
            if j >= len(path):
                raise ValueError("unclosed bracket in path")

            index_str = path[i+1:j]

            # Validate index: must be non-negative integer
            if not index_str:
                raise ValueError("empty index in path")

            if index_str.startswith('-'):
                raise ValueError("negative indices not allowed")

            if not index_str.isdigit():
                raise ValueError("index must be a non-negative integer")

            steps.append(f"[{index_str}]")
            i = j  # Move to the closing bracket
        else:
            current += ch
        i += 1

    if current:
        steps.append(current)

    if not steps:
        raise ValueError("path is empty or malformed")

    # First step must be a key (not an index)
    if steps[0].startswith('['):
        raise ValueError("first step must be a key")

    # Deep copy the object to ensure immutability of the original
    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy(item) for item in o]
        else:
            return o

    result = deep_copy(obj)

    node = result

    # Navigate through all steps except the last one
    for step in steps[:-1]:
        if step.startswith('['):
            # Index step
            idx = int(step[1:-1])
            if not isinstance(node, list):
                raise TypeError("cannot index into a non-list")

            # Handle padding or appending
            if idx == len(node):
                node.append(None)
            elif idx > len(node):
                node.extend([None] * (idx - len(node)))

            # If the target is None, we need to create a list for the next step
            # But we don't know the next step yet, so we'll handle it in the next iteration
            if node[idx] is None:
                # Look ahead to see if next step is index or key
                next_step = steps[steps.index(step) + 1] if steps.index(step) + 1 < len(steps) else None
                if next_step and next_step.startswith('['):
                    node[idx] = []
                else:
                    node[idx] = {}

            node = node[idx]
        else:
            # Key step
            if not isinstance(node, dict):
                raise TypeError("cannot use key on a non-dict")

            if step not in node:
                # Look ahead to determine what to create
                next_step = steps[steps.index(step) + 1] if steps.index(step) + 1 < len(steps) else None
                if next_step and next_step.startswith('['):
                    node[step] = []
                else:
                    node[step] = {}

            node = node[step]

    # Handle the last step
    last_step = steps[-1]
    if last_step.startswith('['):
        idx = int(last_step[1:-1])
        if not isinstance(node, list):
            raise TypeError("cannot index into a non-list")

        if idx == len(node):
            node.append(value)
        elif idx > len(node):
            node.extend([None] * (idx - len(node)))
            node[idx] = value
        else:
            node[idx] = value
    else:
        if not isinstance(node, dict):
            raise TypeError("cannot use key on a non-dict")
        node[last_step] = value

    return result
