    # Validate and parse path
    if not path or path.startswith(".") or path.startswith("["):
        raise ValueError("Path must be non-empty and start with a key")
    if ".." in path:
        raise ValueError("Path contains empty key")
    if path.endswith("."):
        raise ValueError("Path ends with empty key")

    # Parse path into steps
    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError("Empty key in path")
            steps.append(('key', current))
            current = ""
        elif ch == '[':
            if current != "":
                steps.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j >= len(path):
                raise ValueError("Unclosed bracket in path")
            index_str = path[i+1:j]
            if index_str == "":
                raise ValueError("Empty index in path")
            if index_str.startswith('-'):
                raise ValueError("Negative indexes not supported")
            try:
                idx = int(index_str)
            except ValueError:
                raise ValueError(f"Invalid index: {index_str}")
            if idx < 0:
                raise ValueError("Negative indexes not supported")
            steps.append(('index', idx))
            i = j
        elif ch == ']':
            raise ValueError("Unexpected closing bracket")
        else:
            current += ch
        i += 1

    if current != "":
        steps.append(('key', current))

    if not steps:
        raise ValueError("Empty path")

    if steps[0][0] != 'key':
        raise ValueError("First step must be a key")

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    # Deep copy the object to ensure immutability of original
    result = copy.deepcopy(obj)

    # Navigate and build the path
    node = result
    for step_type, step_val in steps[:-1]:
