            if step_val > len(node):
                # Pad with None
                node.extend([None] * (step_val - len(node)))
            elif step_val == len(node):
                node.append(None)
            node = node[step_val]

    # Set the final value
    last_type, last_val = steps[-1]
    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError(f"Expected dict at path, got {type(node).__name__}")
        node[last_val] = value
    else:  # index
        if not isinstance(node, list):
            raise TypeError(f"Expected list at path, got {type(node).__name__}")
        if last_val > len(node):
            node.extend([None] * (last_val - len(node)))
