def set_path(obj, path, value):
    """
    Returns a new structure where the location named by path holds value.
    obj and everything reachable from it is left untouched (deep copy semantics).

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing list indices: index == len appends, index > len pads with None.
    - Type mismatch (key on list/scalar, index on dict/scalar) raises TypeError.
    - Empty/malformed path raises ValueError.
    - First step must be a key; obj must be a dict.
    """
    import copy

    # Validate path
    if not path or path.startswith(".") or path.startswith("["):
        raise ValueError("Path must be non-empty and start with a key")
    if ".." in path:
        raise ValueError("Path contains empty key")
    if path.endswith("."):
        raise ValueError("Path ends with empty key")

    # Parse path into steps
    # Replace [ with .[ then split, but handle the first element specially
    parts = []
    current = ""
    i = 0
    while i < len(path):
        if path[i] == '.':
            if current:
                parts.append(current)
                current = ""
            # Check for malformed: . followed by nothing or another .
            if i + 1 >= len(path) or path[i + 1] == '.':
                raise ValueError("Empty key in path")
        elif path[i] == '[':
            if current:
                parts.append(current)
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '.' or path[j] == '[':
                    raise ValueError("Malformed index in path")
                j += 1
            if j >= len(path):
                raise ValueError("Unclosed bracket in path")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError("Empty index in path")
            if not index_str.isdigit():
                raise ValueError("Non-numeric index in path")
            parts.append(('index', int(index_str)))
            i = j
        else:
            current += path[i]
        i += 1

    if current:
        if current.startswith('[') or current.endswith(']'):
            raise ValueError("Malformed path component")
        parts.append(current)

    if not parts:
        raise ValueError("Empty path")

    # First step must be a key
    if isinstance(parts[0], tuple):
        raise ValueError("First step must be a key")

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    # Deep copy to ensure immutability of original
    result = copy.deepcopy(obj)

    # Navigate and build structure
    node = result

    for i, step in enumerate(parts[:-1]):
        next_step = parts[i + 1]

        if isinstance(step, tuple):
            # Index step
            idx = step[1]
            if not isinstance(node, list):
                raise TypeError(f"Cannot index into non-list at step {i}")

            # Handle missing indices
            while len(node) <= idx:
                node.append(None)

            next_val = node[idx]
            is_next_index = isinstance(next_step, tuple)

            if next_val is None:
                if is_next_index:
                    node[idx] = []
                else:
                    node[idx] = {}
            elif is_next_index and not isinstance(next_val, list):
                raise TypeError(f"Expected list at step {i+1}, got {type(next_val).__name__}")
            elif not is_next_index and not isinstance(next_val, dict):
                raise TypeError(f"Expected dict at step {i+1}, got {type(next_val).__name__}")

            node = node[idx]
        else:
            # Key step
            key = step
            if not isinstance(node, dict):
                raise TypeError(f"Cannot use key on non-dict at step {i}")

            is_next_index = isinstance(next_step, tuple)

            if key not in node:
                if is_next_index:
                    node[key] = []
                else:
                    node[key] = {}
            elif is_next_index and not isinstance(node[key], list):
                raise TypeError(f"Expected list at step {i+1}, got {type(node[key]).__name__}")
            elif not is_next_index and not isinstance(node[key], dict):
                raise TypeError(f"Expected dict at step {i+1}, got {type(node[key]).__name__}")

            node = node[key]

    # Set the final value
    last_step = parts[-1]
    if isinstance(last_step, tuple):
        idx = last_step[1]
        if not isinstance(node, list):
            raise TypeError("Cannot index into non-list for final assignment")
        while len(node) <= idx:
            node.append(None)
        node[idx] = value
    else:
        key = last_step
        if not isinstance(node, dict):
            raise TypeError("Cannot use key on non-dict for final assignment")
        node[key] = value

    return result
