class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        # Clean expired lots and gather usable ones
        usable = []
        remaining = []
        for lot in self.lots.get(sku, []):
            exp, q = lot
            if today > exp:
                # Expired: drop
                continue
            if q > 0:
                usable.append((exp, q, len(usable)))  # track original insertion order via index
            else:
                remaining.append(lot)

        # Sort by earliest expiry, then by original insertion order (FIFO for same expiry)
        usable.sort(key=lambda x: (x[0], x[2]))

        taken = []
        needed = qty

        for exp, q, _ in usable:
            if needed == 0:
                break
            n = min(needed, q)
            taken.append((exp, n))
            needed -= n

        if needed > 0:
            raise ValueError("insufficient")

        # Rebuild the lot list: apply deductions in order, keep leftovers
        # We need to deduct from the actual stored lots in the correct order
        # Reconstruct usable list again to map deductions back
        usable_again = []
        for lot in self.lots.get(sku, []):
            exp, q = lot
            if today <= exp and q > 0:
                usable_again.append([exp, q])
        usable_again.sort(key=lambda x: x[0])  # stable sort preserves insertion order for ties

        # Apply deductions from taken list
        taken_idx = 0
        new_lots = []
        for lot in usable_again:
            if taken_idx >= len(taken):
                break
            exp_take, qty_take = taken[taken_idx]
            # Match lot to taken (by expiry and order)
            if lot[0] == exp_take:
                if lot[1] > qty_take:
                    lot[1] -= qty_take
                    new_lots.append(lot)
                    taken_idx += 1
                elif lot[1] == qty_take:
                    taken_idx += 1
                else:
                    # lot smaller than needed; consume lot and move to next taken
                    qty_take -= lot[1]
                    taken[taken_idx] = (exp_take, qty_take)
                    taken_idx += 1
            else:
                new_lots.append(lot)

        # Append any leftover lots that weren't touched (shouldn't happen if logic is tight, but safe)
        # Actually, rebuild cleanly: iterate original, drop expired, apply taken in order
        final_lots = []
        taken_ptr = 0
        usable_sorted = []
        for lot in self.lots.get(sku, []):
            exp, q = lot
            if today <= exp and q > 0:
                usable_sorted.append([exp, q])
        usable_sorted.sort(key=lambda x: x[0])

        for lot in usable_sorted:
            if taken_ptr >= len(taken):
                final_lots.append(lot)
                continue
            exp_take, qty_take = taken[taken_ptr]
            if lot[0] == exp_take:
                if lot[1] > qty_take:
                    lot[1] -= qty_take
                    final_lots.append(lot)
                    taken_ptr += 1
                elif lot[1] == qty_take:
                    taken_ptr += 1
                else:
                    # lot fully consumed, move to next taken with reduced need
                    taken[taken_ptr] = (exp_take, qty_take - lot[1])
                    taken_ptr += 1
            else:
                final_lots.append(lot)

        # Add back any non-expired lots that had zero qty originally (edge case)
        for lot in self.lots.get(sku, []):
            if today <= lot[0] and lot[1] == 0:
                # Keep zero-qty lots? Usually we drop them, but spec doesn't say.
                # Dropping zero-qty lots is cleaner.
                pass

        self.lots[sku] = final_lots
        return taken

    def stock(self, sku, today):
        total = 0
        for lot in self.lots.get(sku, []):
            exp, q = lot
            if today <= exp:
                total += q
        # Clean up expired lots while we're at it
        self.lots[sku] = [[exp, q] for exp, q in self.lots.get(sku, []) if today <= exp]
        return total
