        # Return a deep enough copy so callers can mutate it (including nested dicts)
        # without affecting the cache or future reads.
        return dict(self.cache[uid])

    def update_profile(self, uid, changes):
        profile = self._load(uid)
        profile.update(changes)
        self.db[uid] = profile
        # Invalidate cache using the correct key (uid, not str(uid))
        self.cache.pop(uid, None)
