            return 0

        # Snapshot the current list of handlers to avoid issues with modifications during iteration
        # We only call handlers that are present at the start of emit
        snapshot = list(self.subs[topic])

        n = 0
        for _, _, h in snapshot:
            # Check if this specific subscription still exists before calling
            # This handles the case where an earlier handler unsubscribed a later one
            if topic in self.subs and (_, _, h) in self.subs[topic]:
                # We need to be careful here: the snapshot contains (priority, index, handler)
                # But the actual list might have been modified. 
                # The requirement says: "a handler that was unsubscribed by an earlier handler in the same emit is NOT called"
