        self.subs[topic].append(entry)
        # Sort: higher priority first; equal priorities in subscription order
        self.subs[topic].sort(key=lambda x: (-x['priority'], self.subs[topic].index(x)))

        def unsubscribe():
            if topic in self.subs:
                # Find and remove only this specific subscription
                for i, sub in enumerate(self.subs[topic]):
                    if sub['id'] == entry['id']:
                        # If currently emitting, mark for removal after emit
