def load_config(defaults, env, prefix="APP_"):
    def _deep_copy(obj):
        if isinstance(obj, dict):
            return {k: _deep_copy(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_deep_copy(item) for item in obj]
        return obj

    def _convert_value(value, target):
        if isinstance(target, bool):
            if isinstance(value, str):
                val_lower = value.lower()
                if val_lower in ("1", "true", "yes", "on"):
                    return True
                if val_lower in ("0", "false", "no", "off"):
                    return False
                raise ValueError(f"Invalid boolean value: {value}")
            return bool(value)
        if isinstance(target, int):
            return int(value)
        if isinstance(target, float):
            return float(value)
        return str(value)

    def _set_nested(d, keys, value):
        node = d
        for key in keys[:-1]:
            if key not in node or not isinstance(node[key], dict):
                return  # Ignore paths that don't exist in defaults
            node = node[key]
        if keys[-1] in node:
            node[keys[-1]] = value

    cfg = _deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        suffix = k[len(prefix):]
        # Split only on double underscores for nesting, single underscores are part of the key
        parts = suffix.split("__")
        path = [p.lower() for p in parts]

        # Navigate to check if path exists and get the default value for type conversion
        node = cfg
        valid_path = True
        for p in path[:-1]:
            if p not in node or not isinstance(node[p], dict):
                valid_path = False
                break
            node = node[p]

        if not valid_path:
            continue

        if path[-1] not in node:
            continue

        default_val = node[path[-1]]

        try:
            converted_val = _convert_value(raw, default_val)
        except ValueError:
            raise ValueError(f"Cannot convert '{raw}' to type of default value for key '{k}'")

        _set_nested(cfg, path, converted_val)

    return cfg
