def load_config(defaults, env, prefix="APP_"):
    """
    Build a new config dict from defaults, overridden by environment variables.

    Rules:
      - Only variables starting with `prefix` are considered.
      - The suffix after the prefix is lowercased and split on "__" (double underscore)
        to form the nested path. A single underscore is part of the key name.
      - The raw string is converted to the type of the existing default value:
          * bool: accepts "1/true/yes/on" or "0/false/no/off" (case-insensitive);
            anything else raises ValueError.
          * int/float: parsed numerically.
          * other: kept as string.
      - Variables whose path does not exist in defaults are ignored.
      - The defaults object is never modified; a new dict (and nested dicts) is returned.
    """

    def _convert(value, target_type):
        if target_type is bool:
            v = value.lower()
            if v in ("1", "true", "yes", "on"):
                return True
            if v in ("0", "false", "no", "off"):
                return False
            raise ValueError(f"Invalid boolean value: {value!r}")
        if target_type is int:
            return int(value)
        if target_type is float:
            return float(value)
        # For any other type, assume string
        return value

    def _deep_copy(node):
        if isinstance(node, dict):
