def load_config(defaults, env, prefix="APP_"):
    """
    Build a new config dict from defaults, overridden by environment variables.

    Rules:
      - Only env keys starting with `prefix` are considered.
      - The suffix after the prefix is lowercased, then split on double
        underscores "__" to form a path. A single underscore is part of the key.
      - The path must exist in `defaults`; otherwise the variable is ignored.
      - The raw string is converted to the type of the default value:
          * bool: accepts 1/true/yes/on and 0/false/no/off (case-insensitive);
            anything else raises ValueError.
          * int/float: parsed numerically.
          * other: kept as string.
      - `defaults` is never modified; a new dict (and nested dicts) are created.
    """

    def _convert(value, target_type):
        if target_type is bool:
            v = value.strip().lower()
            if v in ("1", "true", "yes", "on"):
                return True
            if v in ("0", "false", "no", "off"):
                return False
            raise ValueError(f"Invalid boolean value: {value!r}")
        if target_type is int:
            return int(value)
        if target_type is float:
            return float(value)
        # For any other type, assume string
        return str(value)

    def _deep_copy(obj):
        if isinstance(obj, dict):
            return {k: _deep_copy(v) for k, v in obj.items()}
        # Shallow copy for non-dict values is sufficient
        return obj

    cfg = _deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        suffix = k[len(prefix):]
        # Split on double underscore for nesting; single underscore is part of key
        path = suffix.lower().split("__")

        # Traverse to the parent node
        node = cfg
        valid = True
        for p in path[:-1]:
            if not isinstance(node, dict) or p not in node:
                valid = False
                break
            node = node[p]

        if not valid:
            continue

        leaf_key = path[-1]
        if not isinstance(node, dict) or leaf_key not in node:
            continue

        default_value = node[leaf_key]
        target_type = type(default_value)

        try:
            converted = _convert(raw, target_type)
        except (ValueError, TypeError):
            # Ignore variables that cannot be converted to the expected type
            continue

        node[leaf_key] = converted

    return cfg
```

The bug stems from four distinct issues in the original implementation:
1.  **Shallow Copy**: `dict(defaults)` creates a shallow copy, so nested dictionaries in `defaults` are still referenced directly, causing mutation of the original input.
2.  **Key Parsing**: Splitting by `_` indiscriminately breaks keys that legitimately contain underscores (e.g., `max_conns` becomes `["max", "conns"]` instead of `["max_conns"]`). The spec requires splitting by double underscores `__`.
3.  **Type Conversion**: The code blindly calls `type(default)(raw)`. This fails for `bool` (since `bool("false")` is `True`) and doesn't handle the specific string mappings for booleans requested. It also lacks validation for invalid strings.
4.  **Missing Path Validation**: The code attempts to traverse or assign to paths that don't exist in `defaults`, causing crashes or creating unexpected keys, whereas the spec says to ignore them. It also fails to check if intermediate nodes are dictionaries.

Here is the corrected module:

```python
def load_config(defaults, env, prefix="APP_"):
    """
    Loads configuration from environment variables into a defaults dictionary.

    - Variables starting with `prefix` are processed.
    - The suffix after the prefix is lowercased and split by '__' to determine nesting.
    - Values are cast to the type of the existing default value.
    - Booleans accept specific true/false strings; others raise ValueError.
    - Unknown paths or variables without the prefix are ignored.
    - The `defaults` object is not modified.
    """

    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        return obj

    def parse_bool(val):
        v = val.strip().lower()
        if v in ('1', 'true', 'yes', 'on'):
            return True
        if v in ('0', 'false', 'no', 'off'):
            return False
        raise ValueError(f"Invalid boolean value: {val}")

    def convert_value(val, target_type):
        if target_type is bool:
            return parse_bool(val)
        try:
            return target_type(val)
        except (ValueError, TypeError):
            raise ValueError(f"Cannot convert '{val}' to {target_type.__name__}")

    # Deep copy to ensure defaults is not modified and nested dicts are independent
    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Remove prefix and lowercase
        suffix = k[len(prefix):].lower()

        # Split by double underscore for nesting, single underscore is part of the key
        path = suffix.split('__')

        # Traverse to the parent node
        node = cfg
        valid_path = True

        # Navigate to the parent of the target key
        for part in path[:-1]:
            if not isinstance(node, dict) or part not in node:
                valid_path = False
                break
            node = node[part]

        if not valid_path or not isinstance(node, dict):
            continue

        target_key = path[-1]

        # Check if the key exists in defaults structure
        if target_key not in node:
            continue

        default_val = node[target_key]

        # Determine target type
        target_type = type(default_val)

        # Skip if the default value is a dict (cannot override a dict with a scalar via env)
        if isinstance(default_val, dict):
            continue

        try:
            node[target_key] = convert_value(raw, target_type)
        except ValueError:
            raise ValueError(f"Invalid value for {k}: '{raw}' is not a valid {target_type.__name__}")

    return cfg
