import re


def evaluate(s):
    # Validate input: must not be empty or only whitespace
    if not s or s.strip() == "":
        raise ValueError("Empty input")

    # Check for invalid characters before tokenizing
    # Allowed: digits, dot, + - * / ^ ( ) and whitespace
    if re.search(r"[^\d.\+\-\*/^\(\)\s]", s):
        raise ValueError("Unknown characters in input")

    # Tokenize: numbers (int, float, .float) and operators/parens
    toks = re.findall(r"\d+\.?\d*|\.\d+|[-+*/^()]", s)

    if not toks:
        raise ValueError("No tokens found")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        if pos >= len(toks):
            raise ValueError("Unexpected end of expression")
        t = peek()
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = power()
        while peek() in ("*", "/"):
            op = take()
            r = power()
            v = v * r if op == "*" else v / r
        return v

    def power():
        # Right-associative exponentiation with unary support in exponent
        v = unary()
        if peek() == "^":
            take()
            # Exponent is parsed as unary to allow signs like 2^-1
            exp = unary()
            v = v ** exp
        return v

    def unary():
        t = peek()
        if t in ("+", "-"):
            take()
            val = unary()
            return -val if t == "-" else val
        return power_base()

    def power_base():
        # Handles atoms and potential chained ^ (though ^ is handled in power())
        # This function is essentially the old atom() but without unary logic
        t = take()
        if t == "(":
            v = expr()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            take()
            return v
        if t in ("+", "-", "*", "/", "^", ")"):
            raise ValueError("Missing operand")
        try:
            return float(t)
        except ValueError:
            raise ValueError(f"Invalid number: {t}")

    result = expr()

    if pos != len(toks):
        raise ValueError("Unexpected tokens after expression")

    return result
