        if peek() == "+":
            take()
            return unary()
        if peek() == "-":
            take()
            return -unary()
        return power()

    def power():
        v = atom()
        while peek() == "^":
            take()
            # Right-associative: exponent is unary (allows -2^2 = -(2^2))
            e = unary()
            v = v ** e
        return v

