import re


def evaluate(s):
    # Tokenize: numbers (including decimals), operators, parentheses, and unary signs attached to numbers
    # We need to distinguish unary minus/plus from binary operators during parsing.
    # Strategy: preprocess to mark unary operators, or handle in parser.
    # Better: tokenize numbers and symbols, then in parser handle unary when context allows.

    # First, validate input: remove spaces, check for invalid characters
    stripped = s.replace(" ", "")
    if not stripped:
        raise ValueError("Empty expression")

    # Check for invalid characters
    if re.search(r"[^\d\.+\-*/^()]", stripped):
        raise ValueError("Invalid character in expression")

    # Tokenize into numbers and operators/parens
    # Numbers: digits with optional decimal point
    # Operators: + - * / ^ ( )
    tokens = []
    i = 0
    while i < len(stripped):
        c = stripped[i]
        if c.isdigit() or c == '.':
            j = i
            has_dot = (c == '.')
            while j < len(stripped) and (stripped[j].isdigit() or (stripped[j] == '.' and not has_dot)):
                if stripped[j] == '.':
                    has_dot = True
                j += 1
            tokens.append(('NUM', float(stripped[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append(('OP', c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expect_num():
        t = take()
        if t is None or t[0] != 'NUM':
            raise ValueError("Expected number")
        return t[1]

    def expr():
        # + and - (left to right), loosest
        v = term()
        while True:
            t = peek()
            if t is None:
                break
            if t[0] == 'OP' and t[1] in ('+', '-'):
                op = take()[1]
                r = term()
                v = v + r if op == '+' else v - r
            else:
                break
        return v

    def term():
        # * and / (left to right)
        v = power()
        while True:
            t = peek()
            if t is None:
                break
            if t[0] == 'OP' and t[1] in ('*', '/'):
                op = take()[1]
                r = power()
                if op == '/':
                    if r == 0:
                        raise ZeroDivisionError("Division by zero")
                    v = v / r
                else:
                    v = v * r
            else:
                break
        return v

    def power():
        # ^ (right-associative), tighter than * /
        # But unary minus/plus is tighter than ^, and exponent may carry a sign
        # So: base = unary(), then if ^, exponent = unary() (not power(), to avoid left-recursion issues with right-assoc)
        # Actually for right-associative: 2^3^2 = 2^(3^2) = 512
        # So: v = unary(); if ^ then v = v ** power() (recursive on right)

        v = unary()
        t = peek()
        if t is not None and t[0] == 'OP' and t[1] == '^':
            take()
            exp = power()  # right-associative: recurse on right
            v = v ** exp
        return v

    def unary():
        # unary minus/plus, tightest before atom
        t = peek()
        if t is not None and t[0] == 'OP' and t[1] in ('+', '-'):
            op = take()[1]
            val = unary()  # allow chained: --3
            return -val if op == '-' else val
        return atom()

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        if t[0] == 'NUM':
            take()
            return t[1]
        if t[0] == 'OP' and t[1] == '(':
            take()
            v = expr()
            t = peek()
            if t is None or t[0] != 'OP' or t[1] != ')':
                raise ValueError("Missing closing parenthesis")
            take()
            return v
        # If we see an operator here, it's an error (missing operand)
        if t[0] == 'OP':
            raise ValueError(f"Unexpected operator: {t[1]}")
        raise ValueError("Invalid token")

    result = expr()

    # Ensure all tokens consumed
    if peek() is not None:
        raise ValueError("Unexpected trailing content")

    return result
