import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parens. Ignore whitespace.
    # Raise ValueError on unknown characters.
    token_pattern = re.compile(r"\s*(?:(\d+\.?\d*|\.\d+)|([-+*/^()])|(\S))")
    toks = []
    for m in token_pattern.finditer(s):
        num, op, garbage = m.groups()
        if garbage is not None:
            raise ValueError(f"Invalid character: {garbage}")
        if num is not None:
            toks.append(("NUM", float(num)))
        else:
            toks.append(("OP", op))

    if not toks:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expect_number():
        t = peek()
        if t is None or t[0] != "NUM":
            raise ValueError("Missing operand")
        return take()[1]

    def expr():
        # + and - (left to right)
        v = term()
        while True:
            t = peek()
            if t is None or t[0] != "OP" or t[1] not in ("+", "-"):
                break
            op = take()[1]
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        # * and / (left to right)
        v = power()
        while True:
            t = peek()
            if t is None or t[0] != "OP" or t[1] not in ("*", "/"):
                break
            op = take()[1]
            r = power()
            if op == "/" and r == 0:
                raise ZeroDivisionError("division by zero")
            v = v * r if op == "*" else v / r
        return v

    def power():
        # ^ (right-associative), unary binds tighter than ^, but exponent may carry sign
        # So we parse: atom { ^ unary_power }?  where unary_power handles leading +/-
        v = atom()
        while True:
            t = peek()
            if t is None or t[0] != "OP" or t[1] != "^":
                break
            take()  # consume '^'
            # Right-associative: parse the rest as a unary-aware power chain
            exp = unary_signed_power()
            v = v ** exp
        return v

    def unary_signed_power():
        # Handles leading unary + or - for the exponent, then atom and further ^
        t = peek()
        if t is not None and t[0] == "OP" and t[1] in ("+", "-"):
            op = take()[1]
            base = atom()
            # Continue with right-associative ^ if present
            while True:
                tt = peek()
                if tt is None or tt[0] != "OP" or tt[1] != "^":
                    break
                take()
                base = base ** unary_signed_power()
            return -base if op == "-" else base
        else:
            return power()

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t[0] == "NUM":
            return take()[1]
        if t[0] == "OP":
            if t[1] == "(":
                take()
                v = expr()
                if peek() is None or peek()[0] != "OP" or peek()[1] != ")":
                    raise ValueError("Missing closing parenthesis")
                take()
                return v
            if t[1] == ")":
                raise ValueError("Unexpected closing parenthesis")
            # Unary + or - at atom level (for things like --3 or -2^2 handled via power/unary chain)
            if t[1] in ("+", "-"):
                # This path is for unary at the very atom level when not part of exponent chain
                # But our grammar routes unary in exponents through unary_signed_power.
                # For top-level or parenthesized expressions, unary is handled before calling atom
                # in the original design; however, to support --3, we need unary here too.
                # We'll delegate to a small helper that mimics the original intent but safely.
                op = take()[1]
                val = atom()
                return -val if op == "-" else val
        raise ValueError(f"Unexpected token: {t}")

    # Wrap the top-level parse to ensure full consumption and correct unary handling
    # The original code allowed unary only inside atom; we preserve that but fix precedence.
    # To correctly handle "-2^2" as "-(2^2)", unary minus must bind looser than ^.
    # Our structure: expr -> term -> power -> atom, with unary handled in power/exponent path.
    # For leading unary at the very start, we handle it before calling expr.
    def parse():
        t = peek()
        if t is None:
            raise ValueError("Empty expression")
        # Handle leading unary operators (e.g., --3, -2^2)
        if t[0] == "OP" and t[1] in ("+", "-"):
            ops = []
            while True:
                tt = peek()
                if tt is None or tt[0] != "OP" or tt[1] not in ("+", "-"):
                    break
                ops.append(take()[1])
            base = expr()
            # Apply unary operators from right to left? Actually, --3 = -(-3) = 3, so left to right application of negation
            # But mathematically, - - 3 = (-1)*((-1)*3) = 3. So we apply from left to right as accumulated sign.
            sign = 1
            for op in ops:
                if op == "-":
                    sign = -sign
            return sign * base
        return expr()

    result = parse()

    if pos != len(toks):
        raise ValueError("Unexpected trailing tokens")

    return result
```

Based on the ticket and source code, here are the specific defects identified:

1.  **Weight Reset**: In `add`, `node["$"] = weight` overwrites the existing weight instead of accumulating (`+=`).
2.  **Sort Order**: `found.sort(reverse=True)` sorts by weight descending (correct) but then by word descending (incorrect; should be alphabetical/ascending for ties). The tuple `(weight, word)` with `reverse=True` flips both.
3.  **Slice Off-By-One**: `found[:k - 1]` returns one fewer item than requested. It should be `[:k]`.
4.  **Case Sensitivity**: In `suggest`, the loop `for ch in prefix:` does not lowercase the input, so uppercase prefixes fail to match the lowercased trie keys.
5.  **Special Character Collision**: The marker `"$"` is used to denote the end of a word. If a word contains `"$"`, the trie structure conflates the word's internal character node with the end-of-word marker of a prefix, causing data corruption/mix-ups. A control character (like `\0`) that cannot appear in normal input should be used instead.

Here is the corrected module:

```python
class Autocomplete:
    def __init__(self):
        self.root = {}
        self.size = 0
        self._END_MARKER = "\0"  # Use a control char to avoid collision with valid word chars like "$"

    def add(self, word, weight=1):
        node = self.root
        for ch in word.lower():
            node = node.setdefault(ch, {})
        if self._END_MARKER not in node:
            self.size += 1
            node[self._END_MARKER] = 0
        node[self._END_MARKER] += weight

    def remove(self, word):
        node = self.root
        for ch in word.lower():
            if ch not in node:
                return False
            node = node[ch]
        if self._END_MARKER not in node:
            return False
        del node[self._END_MARKER]
        self.size -= 1
        return True

    def suggest(self, prefix, k=5):
        if k <= 0:
            return []
        node = self.root
        for ch in prefix.lower():
            if ch not in node:
                return []
            node = node[ch]
        found = []

        def walk(n, acc):
            for key, child in n.items():
                if key == self._END_MARKER:
                    found.append((child, acc))
                else:
                    walk(child, acc + key)

        walk(node, prefix.lower())
        # Sort by weight descending (-weight), then by word ascending (word)
        found.sort(key=lambda x: (-x[0], x[1]))
        return [w for _, w in found[:k]]

    def __len__(self):
        return self.size
