def set_path(obj, path, value):
    """
    Returns a new structure where the location named by path holds value.
    The original obj and everything reachable from it is left untouched.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path:
        raise ValueError("Path cannot be empty")

    # Validate path format before processing
    if path.startswith(".") or path.endswith("."):
        raise ValueError("Malformed path: cannot start or end with '.'")
    if ".." in path:
        raise ValueError("Malformed path: cannot contain empty segments")

    # Check for invalid index formats like [-1], [x], or unclosed [
    import re
    # Find all bracketed sections
    bracket_parts = re.findall(r'\[([^\]]*)\]', path)
    for part in bracket_parts:
        if not part:
            raise ValueError("Malformed path: empty brackets")
        if not part.isdigit():
            raise ValueError(f"Malformed path: invalid index '{part}'")
        if part.startswith('0') and len(part) > 1:
            # Allow "0" but not "01", though strictly speaking Python allows leading zeros in int()
            # The ticket doesn't forbid leading zeros explicitly, but standard practice usually does.
            # However, let's stick to the ticket: "a[-1]", "a[x]" are bad. "a[01]" is technically an int.
            # Let's just ensure it's a valid non-negative integer string.
            pass
        if int(part) < 0:
            raise ValueError("Malformed path: negative index")

    # Check for unclosed brackets or brackets in wrong places roughly
    # A simple state machine or regex can ensure structure like key[idx].key
    # The ticket examples: "a.b[2].c", "items[0]"
    # Split logic needs to be robust.

    # Let's parse manually to be safe and build a token list
    tokens = []
    current_key = ""
    i = 0
    while i < len(path):
        char = path[i]
        if char == '.':
            if current_key:
                tokens.append(('key', current_key))
                current_key = ""
            elif not tokens: 
                # Starts with dot handled above, but double check logic
                pass
            i += 1
        elif char == '[':
            if current_key:
                tokens.append(('key', current_key))
                current_key = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j == len(path):
                raise ValueError("Malformed path: unclosed bracket")
            index_str = path[i+1:j]
            if not index_str.isdigit():
                raise ValueError(f"Malformed path: invalid index '{index_str}'")
            tokens.append(('index', int(index_str)))
            i = j + 1
        else:
            current_key += char
            i += 1

    if current_key:
        tokens.append(('key', current_key))

    if not tokens:
        raise ValueError("Path cannot be empty")

    if tokens[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Deep copy function to ensure immutability of original
    def deep_copy(item):
        if isinstance(item, dict):
            return {k: deep_copy(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [deep_copy(v) for v in item]
        else:
            return item

    result = deep_copy(obj)

    node = result

    # Navigate to the parent of the target location
    # We need to process all tokens except the last one
    for i in range(len(tokens) - 1):
        step_type, step_val = tokens[i]
        next_type, next_val = tokens[i+1]

        if step_type == 'key':
            if not isinstance(node, dict):
                raise TypeError("Cannot use key step on non-dict")

            if step_val not in node:
                # Create missing container based on next step
                if next_type == 'index':
                    node[step_val] = []
                else:
                    node[step_val] = {}

            node = node[step_val]

        elif step_type == 'index':
            if not isinstance(node, list):
                raise TypeError("Cannot use index step on non-list")

            # Handle padding if index is out of bounds
            if step_val >= len(node):
                # Pad with None up to step_val
                padding = [None] * (step_val - len(node) + 1)
                node.extend(padding)

            # Check if the current value at index is compatible with next step if it exists
            current_item = node[step_val]
            if current_item is None:
                # We need to initialize it based on the next step
                if next_type == 'index':
                    node[step_val] = []
                else:
                    node[step_val] = {}
            elif next_type == 'key' and not isinstance(current_item, dict):
                raise TypeError("Cannot use key step on non-dict")
            elif next_type == 'index' and not isinstance(current_item, list):
                raise TypeError("Cannot use index step on non-list")

            node = node[step_val]

    # Apply the final value
    last_type, last_val = tokens[-1]

    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError("Cannot set key on non-dict")
        node[last_val] = value
    elif last_type == 'index':
        if not isinstance(node, list):
            raise TypeError("Cannot set index on non-list")

        if last_val >= len(node):
            # Pad list up to last_val
            padding = [None] * (last_val - len(node) + 1)
            node.extend(padding)

        node[last_val] = value

    return result
