def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.

    Rules:
    - Path is dot-separated keys with optional list indexes (e.g., "a.b[2].c").
    - Missing dict keys are created.
    - Missing containers: dict if next step is key, list if next step is index.
    - Index == len(list) appends; index > len(list) pads with None.
    - TypeError if existing value has wrong type for next step.
    - ValueError if path is empty, malformed, or starts with index.
    - First step must be a key; obj must be a dict.
    """
    import copy

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before parsing
    if path.startswith(".") or path.startswith("["):
        raise ValueError("path must start with a key")
    if ".." in path:
        raise ValueError("path contains empty key")

    # Parse path into steps
    # Replace "[index]" with ".[index]" to split correctly, but handle edge cases
    # We need to be careful: "a.b[2].c" -> ["a", "b", "[2]", "c"]
    # But "a[0]" -> ["a", "[0]"]

    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == ".":
            if current:
                steps.append(current)
                current = ""
            # Check for malformed: ".." already caught, but check trailing dot later
        elif ch == "[":
            if current:
                steps.append(current)
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != "]":
                j += 1
            if j >= len(path):
                raise ValueError(f"unclosed bracket in path: {path}")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError(f"empty index in path: {path}")
            if not index_str.isdigit():
                raise ValueError(f"invalid index '{index_str}' in path: {path}")
