class Inventory:
    def __init__(self):
        self.lots = {}

    def _clean_lots(self, sku, today):
        """Remove expired lots and sort remaining lots by expiry (asc), then by insertion order."""
        if sku not in self.lots:
            return

        # Filter out expired lots (usable while today <= expires, so expired if today > expires)
        # We also need to maintain the original insertion order for lots with the same expiry.
        # Since we process in order, we can just filter and then sort stable by expiry.
        usable_lots = [lot for lot in self.lots[sku] if lot[0] >= today]

        # Sort by expiry date (ascending). Python's sort is stable, so original order is preserved for ties.
        usable_lots.sort(key=lambda x: x[0])

        self.lots[sku] = usable_lots

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        # Clean up expired lots and sort the rest before attempting to take
        self._clean_lots(sku, today)

        available_lots = self.lots.get(sku, [])

        # Calculate total usable stock
        total_usable = sum(lot[1] for lot in available_lots)

        if total_usable < qty:
            raise ValueError("insufficient")

        taken = []
        remaining_qty = qty

        for lot in available_lots:
            if remaining_qty == 0:
                break

            take_amount = min(remaining_qty, lot[1])
            lot[1] -= take_amount
            remaining_qty -= take_amount
            taken.append((lot[0], take_amount))

        # Remove lots that have been completely consumed
        self.lots[sku] = [lot for lot in self.lots[sku] if lot[1] > 0]

        return taken

    def stock(self, sku, today):
        self._clean_lots(sku, today)
        return sum(lot[1] for lot in self.lots.get(sku, []))
