    Returns a new structure with the value set at the given path.
    The original obj and all reachable structures are left untouched (deep copy).

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing list indices: index == len appends; index > len pads with None.
    - Type mismatch (key on list/scalar, index on dict/scalar) raises TypeError.
    - Empty, malformed paths, or negative/non-integer indexes raise ValueError.
    - First step must be a key; obj must be a dict.
    """
    import copy

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before parsing
    # Check for empty segments, leading/trailing dots, malformed brackets
    if path.startswith('.') or path.endswith('.'):
        raise ValueError("path cannot start or end with a dot")

    # Check for empty keys between dots
    parts_check = path.split('.')
    for part in parts_check:
        if not part:
            raise ValueError("path contains empty segments")

    # Parse path into steps
    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current:
                steps.append(('key', current))
                current = ""
            i += 1
        elif ch == '[':
            if current:
                steps.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j >= len(path):
                raise ValueError("unclosed bracket in path")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError("empty index in path")
            if index_str.startswith('-'):
                raise ValueError("negative indexes not allowed")
            try:
                idx = int(index_str)
            except ValueError:
                raise ValueError("index must be an integer")
            steps.append(('index', idx))
            i = j + 1
        elif ch == ']':
            # Closing bracket without opening is malformed
            raise ValueError("unmatched closing bracket")
        else:
            current += ch
            i += 1

    if current:
        steps.append(('key', current))

    if not steps:
        raise ValueError("path is empty or malformed")

    if steps[0][0] != 'key':
        raise ValueError("first step must be a key")

    # Deep copy to ensure immutability of original
    result = copy.deepcopy(obj)

    node = result

    # Navigate/create path up to the second-to-last step
    for step_type, step_val in steps[:-1]:
        if step_type == 'key':
            if isinstance(node, dict):
                if step_val not in node:
                    # Determine next step type to decide dict vs list
                    next_type = steps[steps.index((step_type, step_val)) + 1][0]
                    node[step_val] = {} if next_type == 'key' else []
                node = node[step_val]
            elif isinstance(node, list):
                raise TypeError("cannot use key step on a list")
            else:
                raise TypeError("cannot traverse through a scalar")
        elif step_type == 'index':
            if isinstance(node, list):
                idx = step_val
                if idx < 0:
                    raise ValueError("negative indexes not allowed")
                if idx == len(node):
                    node.append(None)
                elif idx > len(node):
                    node.extend([None] * (idx - len(node) + 1))
                # idx < len(node): access existing
                if node[idx] is None:
                    # Determine next step type
                    next_type = steps[steps.index((step_type, step_val)) + 1][0]
                    node[idx] = {} if next_type == 'key' else []
                node = node[idx]
            elif isinstance(node, dict):
                raise TypeError("cannot use index step on a dict")
            else:
                raise TypeError("cannot traverse through a scalar")

    # Set the final value
    last_type, last_val = steps[-1]
    if last_type == 'key':
        if isinstance(node, dict):
            node[last_val] = value
        elif isinstance(node, list):
            raise TypeError("cannot use key step on a list")
        else:
            raise TypeError("cannot set key on a scalar")
    elif last_type == 'index':
        if isinstance(node, list):
            idx = last_val
            if idx < 0:
                raise ValueError("negative indexes not allowed")
            if idx == len(node):
                node.append(value)
            elif idx > len(node):
