        usable = []
        remaining = []
        for lot in self.lots.get(sku, []):
            if today > lot[0]:
                # Expired: drop
                continue
            if lot[1] > 0:
                usable.append(lot)
            # If lot[1] == 0, it's empty and can be dropped implicitly

        # Sort usable lots: earliest expiry first, then earliest added (stable sort preserves insertion order for ties)
        usable.sort(key=lambda x: x[0])

        # Check if we have enough stock
        total_usable = sum(lot[1] for lot in usable)
        if total_usable < qty:
            raise ValueError("insufficient")

        taken = []
        remaining_qty = qty

        for lot in usable:
            if remaining_qty == 0:
                break
            n = min(remaining_qty, lot[1])
            lot[1] -= n
            remaining_qty -= n
            taken.append((lot[0], n))

        # Reconstruct the lot list for this SKU: remaining usable lots + any that were not touched
        # We need to preserve the original list structure but remove consumed lots
        new_lots = []
        for lot in self.lots.get(sku, []):
            if today > lot[0]:
                continue  # Skip expired
            if lot[1] > 0:
                new_lots.append(lot)

        self.lots[sku] = new_lots

        if remaining_qty:
            # This should not happen given the check above, but for safety
            raise ValueError("insufficient")

        return taken

