def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from defaults, overridden by environment variables.

    - A variable named PREFIX + PATH overrides the value at that path.
    - PATH is lower-cased and double underscores separate nesting levels.
    - Single underscores are part of the key name.
    - Raw strings are converted to the type of the default value.
    - Bool accepts: 1/true/yes/on and 0/false/no/off (case-insensitive).
    - Unknown paths or variables without prefix are ignored.
    - The defaults object is not modified.
    """

    def deep_copy(obj):
        """Create a deep copy of nested dicts/lists without importing copy."""
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [deep_copy(item) for item in obj]
        else:
            return obj

    def parse_bool(value):
        """Parse string to boolean with strict validation."""
        v = value.strip().lower()
        if v in ("1", "true", "yes", "on"):
            return True
        elif v in ("0", "false", "no", "off"):
            return False
        else:
            raise ValueError(f"Invalid boolean value: {value}")

    def convert_value(target_type, raw):
        """Convert raw string to target type."""
        if target_type is bool:
            return parse_bool(raw)
        elif target_type is int:
            return int(raw)
        elif target_type is float:
            return float(raw)
        else:
            # For str or any other type, return as string or attempt conversion
            return target_type(raw)

    def set_nested_value(node, path, value):
        """Set a value in a nested dict structure, creating intermediate dicts if needed."""
        for key in path[:-1]:
            if key not in node:
                node[key] = {}
            elif not isinstance(node[key], dict):
                # Path conflict: intermediate node is not a dict
                return
            node = node[key]

        final_key = path[-1]
        if final_key in node:
            target_type = type(node[final_key])
            try:
                node[final_key] = convert_value(target_type, value)
            except (ValueError, TypeError):
                # Invalid conversion, skip this variable
                pass
        # If key doesn't exist in defaults structure, ignore (as per spec)

    # Deep copy defaults to avoid modification
    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Extract path: remove prefix, lowercase, split by double underscore
        path_str = k[len(prefix):].lower()

        # Split by double underscore for nesting, single underscore is part of key
        path = path_str.split("__")

        # Validate path exists in defaults before attempting to set
        node = cfg
        valid_path = True
        for p in path[:-1]:
            if p not in node or not isinstance(node[p], dict):
                valid_path = False
                break
            node = node[p]

        if not valid_path:
            continue

        if path[-1] not in node:
            continue

        # Path exists, perform the conversion and set
        try:
            set_nested_value(cfg, path, raw)
        except (ValueError, TypeError, KeyError):
            # Invalid value or path issue, skip this variable
            continue

    return cfg
