        return v

    def unary():
        t = peek()
        if t == "+":
            take()
            return unary()
        if t == "-":
            take()
            return -unary()
        return power()

    def power():
        t = peek()
        if t is None or t in ("+", "-", "*", "/", "^", ")", "("):
            raise ValueError("Missing operand for exponentiation")
        v = atom()
        while peek() == "^":
            take()
            # Right-associative: exponent is a unary expression
            exp = unary()
            v = v ** exp
        return v

