def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.

    Rules:
    - Path is dot-separated keys with optional list indexes (e.g., "a.b[2].c").
    - Missing dict keys are created as dicts.
    - Missing containers for index steps are created as lists.
    - Index equal to list length appends; larger index pads with None.
    - TypeError if existing value has wrong type for next step.
    - ValueError if path is empty or malformed.
    - First step must be a key and obj must be a dict.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or path.startswith(".") or path.endswith("."):
        raise ValueError("Path is empty or malformed")

    # Validate and parse path
    parts = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError("Malformed path: empty segment")
            parts.append(('key', current))
            current = ""
        elif ch == '[':
            if current != "":
                parts.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '[':
                    raise ValueError("Malformed path: nested brackets")
                j += 1
            if j >= len(path):
                raise ValueError("Malformed path: unclosed bracket")
            index_str = path[i+1:j]
            if index_str == "":
                raise ValueError("Malformed path: empty index")
            if index_str.startswith('-') or not index_str.isdigit():
                raise ValueError("Malformed path: invalid index")
            parts.append(('index', int(index_str)))
            i = j
        else:
            current += ch
        i += 1

    if current != "":
        parts.append(('key', current))

    if not parts:
        raise ValueError("Path is empty")

    if parts[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Deep copy function to ensure no shared mutable state
    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy(item) for item in o]
        else:
            return o

    result = deep_copy(obj)

    # Navigate and build structure
    node = result
    for step_type, step_val in parts[:-1]:
        if step_type == 'key':
            if not isinstance(node, dict):
                raise TypeError("Cannot use key on non-dict")
            if step_val not in node:
                # Determine next step type to decide what to create
                next_type, _ = parts[parts.index((step_type, step_val)) + 1] if parts.index((step_type, step_val)) + 1 < len(parts) else ('key', None)
                # Actually we need to look ahead properly
                idx = parts.index((step_type, step_val))
                if idx + 1 < len(parts):
                    next_step_type, _ = parts[idx + 1]
                else:
                    next_step_type = 'key'

                if next_step_type == 'index':
                    node[step_val] = []
                else:
                    node[step_val] = {}
            node = node[step_val]
        else:  # index
            if not isinstance(node, list):
                raise TypeError("Cannot use index on non-list")
            idx = step_val
            if idx < 0:
                raise ValueError("Negative indices not allowed")
            if idx > len(node):
                # Pad with None
                node.extend([None] * (idx - len(node)))
            if idx == len(node):
                node.append(None)
            if node[idx] is None:
                # Determine next step
                curr_idx = parts.index((step_type, step_val))
                if curr_idx + 1 < len(parts):
                    next_step_type, _ = parts[curr_idx + 1]
                else:
                    next_step_type = 'key'

                if next_step_type == 'index':
                    node[idx] = []
                else:
                    node[idx] = {}
            node = node[idx]

    # Set final value
    last_type, last_val = parts[-1]
    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError("Cannot set key on non-dict")
        node[last_val] = value
    else:  # index
        if not isinstance(node, list):
            raise TypeError("Cannot set index on non-list")
        idx = last_val
        if idx < 0:
            raise ValueError("Negative indices not allowed")
        if idx > len(node):
            node.extend([None] * (idx - len(node)))
        if idx == len(node):
            node.append(value)
        else:
            node[idx] = value

    return result
