def set_path(obj, path, value):
    """
    Returns a deep copy of `obj` with `value` set at `path`.

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing list containers are created as lists.
    - Index == len(list) appends.
    - Index > len(list) pads with None up to that index.
    - Wrong type for next step raises TypeError.
    - Empty/malformed path raises ValueError.
    - First step must be a key; obj must be a dict.
    - The original `obj` is never modified.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before processing
    # Check for leading dot, trailing dot, double dots, or malformed brackets
    if path.startswith('.') or path.endswith('.'):
        raise ValueError("path cannot start or end with a dot")
    if '..' in path:
        raise ValueError("path cannot contain empty keys (double dots)")

    # Parse path into steps
    # We need to handle cases like "a.b[2].c" -> ['a', 'b', '[2]', 'c']
    # But also ensure we don't accept invalid bracket syntax
    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current:
                steps.append(current)
                current = ""
            # Skip the dot
            i += 1
            continue
        elif ch == '[':
            # Finish any current key
            if current:
                steps.append(current)
                current = ""
            # Find matching ]
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '[':
                    raise ValueError("nested brackets not allowed")
                j += 1
