                # The spec doesn't forbid leading zeros, just negative or non-numeric.
                pass
            steps.append(f"[{bracket_content}]")
            i = j + 1
            continue
        else:
            current += ch
            i += 1

    if current:
        steps.append(current)

    if not steps:
        raise ValueError("path is empty or malformed")

    # First step must be a key (not an index)
    if steps[0].startswith('['):
        raise ValueError("first step must be a key")

    # Deep copy the object to avoid mutating the original
    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy(item) for item in o]
        else:
            return o

    result = deep_copy(obj)
    node = result

    # Navigate through all steps except the last one, creating containers as needed
    for step in steps[:-1]:
        if step.startswith('['):
            # Index step
            idx = int(step[1:-1])
            if not isinstance(node, list):
                raise TypeError("cannot index into a non-list")
            # Extend list if necessary
            while len(node) <= idx:
                node.append(None)
            # If the next container is None, we need to create it based on the next step
            if node[idx] is None:
                next_step = steps[steps.index(step) + 1]
                if next_step.startswith('['):
                    node[idx] = []
                else:
                    node[idx] = {}
            node = node[idx]
        else:
            # Key step
            if not isinstance(node, dict):
                raise TypeError("cannot use key on a non-dict")
            if step not in node:
                # Determine what to create based on next step
                next_step = steps[steps.index(step) + 1]
                if next_step.startswith('['):
                    node[step] = []
                else:
                    node[step] = {}
            node = node[step]

    # Handle the final step (set the value)
    last_step = steps[-1]
    if last_step.startswith('['):
        idx = int(last_step[1:-1])
        if not isinstance(node, list):
            raise TypeError("cannot index into a non-list")
        # Extend list if necessary
        while len(node) <= idx:
            node.append(None)
        node[idx] = value
    else:
        if not isinstance(node, dict):
            raise TypeError("cannot use key on a non-dict")
        node[last_step] = value

    return result
```

The bug is threefold:
1. **No deep copy**: The function mutates the original `obj` directly instead of creating a new structure.
2. **Missing container creation**: It doesn't create missing dicts or lists along the path.
3. **No list padding**: It doesn't handle appending or padding lists when indices are at or beyond the current length.
4. **No validation**: It doesn't validate the path format or check for type mismatches.

