def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.
    """
    if not isinstance(obj, dict):
        raise TypeError("Root object must be a dict.")
    if not path:
        raise ValueError("Path cannot be empty.")

    # Deep copy helper to ensure no shared mutable state
    def deep_copy(item):
        if isinstance(item, dict):
            return {k: deep_copy(v) for k, v in item.items()}
        if isinstance(item, list):
            return [deep_copy(v) for v in item]
        return item

    root = deep_copy(obj)

    # Parse path into steps: list of ('key', str) or ('index', int)
    # Format: "a.b[2].c" -> [('key', 'a'), ('key', 'b'), ('index', 2), ('key', 'c')]
    tokens = []
    i = 0
    n = len(path)

    while i < n:
        if path[i] == '.':
            raise ValueError(f"Malformed path: unexpected '.' at index {i}")

        # Read key (characters until '[' or '.')
        key_buf = []
        while i < n and path[i] not in ('[', '.'):
            key_buf.append(path[i])
            i += 1

        if key_buf:
            tokens.append(('key', ''.join(key_buf)))

        if i < n and path[i] == '[':
            # Read index
            i += 1  # skip '['
            idx_buf = []
            while i < n and path[i].isdigit():
                idx_buf.append(path[i])
                i += 1

            if i >= n or path[i] != ']':
                raise ValueError(f"Malformed path: expected ']' at index {i}")
            i += 1  # skip ']'

            if not idx_buf:
                raise ValueError("Malformed path: empty index")

            tokens.append(('index', int(''.join(idx_buf))))

    if not tokens:
        raise ValueError("Path cannot be empty.")

    if tokens[0][0] != 'key':
        raise ValueError("First step must be a key.")

    # Navigate and build structure
    current = root
    for step_type, step_val in tokens[:-1]:
        if step_type == 'key':
            if not isinstance(current, dict):
                raise TypeError("Cannot apply key step on non-dict.")
            if step_val not in current:
                # Peek next step to decide container type
                next_type = tokens[tokens.index((step_type, step_val)) + 1][0]
                current[step_val] = [] if next_type == 'index' else {}
            current = current[step_val]
        else:  # index
            if not isinstance(current, list):
                raise TypeError("Cannot apply index step on non-list.")
            idx = step_val
            if idx < 0:
                raise ValueError("Negative indices are not supported.")
            if idx == len(current):
                # Append: decide next container type
                next_type = tokens[tokens.index((step_type, step_val)) + 1][0]
                current.append([] if next_type == 'index' else {})
            elif idx > len(current):
                # Pad with None up to idx, then append new container
                next_type = tokens[tokens.index((step_type, step_val)) + 1][0]
                while len(current) < idx:
                    current.append(None)
                current.append([] if next_type == 'index' else {})
            current = current[idx]

    # Set final value
    last_type, last_val = tokens[-1]
    if last_type == 'key':
        if not isinstance(current, dict):
            raise TypeError("Cannot apply key step on non-dict.")
        current[last_val] = value
    else:  # index
        if not isinstance(current, list):
            raise TypeError("Cannot apply index step on non-list.")
        idx = last_val
        if idx < 0:
            raise ValueError("Negative indices are not supported.")
        if idx == len(current):
            current.append(value)
        elif idx > len(current):
            while len(current) < idx:
                current.append(None)
            current.append(value)
        else:
            current[idx] = value

    return root
