class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def _cleanup_and_sort(self, sku, today):
        """Remove expired lots and return sorted usable lots."""
        if sku not in self.lots:
            return []

        # Filter out expired lots (usable while today <= expires, so expired if today > expires)
        usable_lots = [lot for lot in self.lots[sku] if lot[0] >= today]

        # Sort by expiry date (ascending), then by insertion order (stable sort preserves original order for equal keys)
        # Since we're filtering from the original list which maintains insertion order,
        # a stable sort on expires will give us earliest expiry first, and for equal expiry, earliest added first.
        usable_lots.sort(key=lambda x: x[0])

        # Update the stored lots to only include usable ones (drop expired)
        self.lots[sku] = usable_lots

        return usable_lots

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        usable_lots = self._cleanup_and_sort(sku, today)

        if not usable_lots:
            if qty > 0:
                raise ValueError("insufficient")

        # Calculate total usable stock
        total_usable = sum(lot[1] for lot in usable_lots)
        if total_usable < qty:
            raise ValueError("insufficient")

        taken = []
        remaining_qty = qty

        for lot in usable_lots:
            if remaining_qty == 0:
                break

            n = min(remaining_qty, lot[1])
            lot[1] -= n
            remaining_qty -= n
            taken.append((lot[0], n))

        # Clean up empty lots after taking
        self.lots[sku] = [lot for lot in self.lots[sku] if lot[1] > 0]

        if remaining_qty > 0:
            # This shouldn't happen due to earlier check, but for safety
            raise ValueError("insufficient")

        return taken

    def stock(self, sku, today):
        usable_lots = self._cleanup_and_sort(sku, today)
        return sum(lot[1] for lot in usable_lots)
