def set_path(obj, path, value):
    """
    Returns a new structure where the location named by path holds value.
    obj and everything reachable from it is left untouched (deep copy semantics).

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing list containers are created as lists.
    - Index == len(list) appends.
    - Index > len(list) pads with None up to that index.
    - Wrong type for next step raises TypeError.
    - Empty/malformed path raises ValueError.
    - First step must be a key, obj must be a dict.
    """
    import copy

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before parsing
    if path.startswith('.') or path.endswith('.'):
        raise ValueError(f"Malformed path: {path}")
    if '..' in path:
        raise ValueError(f"Malformed path: {path}")

    # Parse path into parts
    parts = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current:
                parts.append(('key', current))
                current = ""
            elif i == 0 or path[i-1] == '.':
                raise ValueError(f"Malformed path: {path}")
        elif ch == '[':
            if current:
                parts.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '[':
                    raise ValueError(f"Malformed path: {path}")
                j += 1
            if j >= len(path):
                raise ValueError(f"Malformed path: {path}")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError(f"Malformed path: {path}")
            if not index_str.isdigit() or (len(index_str) > 1 and index_str[0] == '0'):
                # Allow "0" but not "00", and no negative or non-digits
                if index_str == "0":
                    pass  # valid
                elif index_str.isdigit():
                    pass  # valid number like "10"
                else:
                    raise ValueError(f"Malformed path: {path}")
            try:
                idx = int(index_str)
            except ValueError:
                raise ValueError(f"Malformed path: {path}")
            if idx < 0:
                raise ValueError(f"Malformed path: {path}")
            parts.append(('index', idx))
            i = j
        else:
            current += ch
        i += 1

    if current:
        parts.append(('key', current))

    if not parts:
        raise ValueError("path must have at least one step")

    # First step must be a key
    if parts[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Deep copy the object to avoid mutating the original
    result = copy.deepcopy(obj)

    node = result

    # Navigate/create path except for the last step
    for step_type, step_val in parts[:-1]:
        if step_type == 'key':
            if isinstance(node, dict):
                if step_val not in node:
                    # Determine what to create based on next step
                    next_type, _ = parts[parts.index((step_type, step_val)) + 1] if (step_type, step_val) in parts else ('key', None)
                    # Actually, we need to look ahead properly
                    idx = parts.index((step_type, step_val))
                    next_type, _ = parts[idx + 1]
                    if next_type == 'key':
                        node[step_val] = {}
                    else:
                        node[step_val] = []
                node = node[step_val]
            else:
                raise TypeError("Cannot access key on non-dict")
        else:  # index
            if isinstance(node, list):
                idx = step_val
                if idx > len(node):
                    # Pad with None
                    node.extend([None] * (idx - len(node)))
                elif idx == len(node):
                    node.append(None)
                node = node[idx]
            else:
                raise TypeError("Cannot access index on non-list")

    # Handle the last step
    last_type, last_val = parts[-1]
    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError("Cannot set key on non-dict")
        node[last_val] = value
    else:  # index
        if not isinstance(node, list):
            raise TypeError("Cannot set index on non-list")
        idx = last_val
        if idx > len(node):
            node.extend([None] * (idx - len(node)))
        elif idx == len(node):
            node.append(value)
            return result
        node[idx] = value

    return result
