        usable.sort(key=lambda x: x[0])
        taken = []
        remaining = qty
        for lot in usable:
            if remaining == 0:
                break
            n = min(remaining, lot[1])
            lot[1] -= n
            remaining -= n
            taken.append((lot[0], n))
        if remaining:
            # Not enough usable stock; do not remove anything
            raise ValueError("insufficient")
        # Remove fully consumed lots and expired lots from the master list
        self.lots[sku] = [lot for lot in lots if lot[1] > 0 and lot[0] >= today]
        if not self.lots[sku]:
            del self.lots[sku]
        return taken

    def stock(self, sku, today):
