        # Drop expired lots
        usable = [lot for lot in lots if lot[0] >= today]
        # Update the stored list to remove expired lots
        if len(usable) != len(lots):
            self.lots[sku] = usable
            if not usable:
                del self.lots[sku]
        return sum(lot[1] for lot in usable)
