class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        usable = []
        for lot in self.lots.get(sku, []):
            exp, remaining = lot
            if today <= exp and remaining > 0:
                usable.append([exp, remaining, lot])  # [exp, remaining, original_ref]

        # Sort by expiry ascending, then by insertion order (stable sort preserves original order for equal exp)
        usable.sort(key=lambda x: x[0])

        required = qty
        taken = []

        for item in usable:
            if required == 0:
                break
            exp, available, original_ref = item
            n = min(required, available)
            original_ref[1] -= n
            required -= n
            taken.append((exp, n))

        if required > 0:
            raise ValueError("insufficient")

        # Clean up expired and empty lots for this SKU
        if sku in self.lots:
            self.lots[sku] = [lot for lot in self.lots[sku] if lot[1] > 0 and today <= lot[0]]
            if not self.lots[sku]:
                del self.lots[sku]

        return taken

    def stock(self, sku, today):
        total = 0
        if sku not in self.lots:
            return 0

        usable_lots = []
        for lot in self.lots[sku]:
            exp, remaining = lot
            if today <= exp and remaining > 0:
                total += remaining
                usable_lots.append(lot)

        # Clean up expired and empty lots
        if usable_lots:
            self.lots[sku] = usable_lots
        else:
            del self.lots[sku]

        return total
