import copy


class ProfileService:
    def __init__(self, db):
        self.db = db
        self.cache = {}
        self.db_reads = 0

    def _load(self, uid):
        self.db_reads += 1
        return copy.deepcopy(self.db[uid])

    def _deep_merge(self, base, updates):
        """Recursively merge updates into base, replacing nested dicts as wholes."""
        result = copy.deepcopy(base)
        for key, value in updates.items():
            if (
                key in result
                and isinstance(result[key], dict)
                and isinstance(value, dict)
            ):
                result[key] = self._deep_merge(result[key], value)
            else:
                result[key] = copy.deepcopy(value)
        return result

    def get_profile(self, uid):
        if uid not in self.cache:
            self.cache[uid] = self._load(uid)
        return copy.deepcopy(self.cache[uid])

    def update_profile(self, uid, changes):
        profile = self._load(uid)
        profile = self._deep_merge(profile, changes)
        self.db[uid] = profile
        self.cache.pop(uid, None)
